@Component({
    selector: 'threadplane-text-transcript',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `
    <section [attr.aria-label]="label()">
      <!-- Explicit role preserves list semantics when markers are hidden in WebKit. -->
      <ol role="list">
        @for (message of messages(); track message.id) {
        <li>
          <span>{{ speakers[message.role] }}</span>
          <p>{{ message.content }}</p>
        </li>
        }
      </ol>
    </section>
  `,
    styles: `
    :host { display: block; color: var(--ds-text-primary, #142435); font-family: inherit; }
    ol { margin: 0; padding: 0; list-style: none; }
    li { margin-block: 1rem; }
    span { font-weight: 600; }
    p { margin-block: .25rem; white-space: pre-wrap; overflow-wrap: anywhere; }
  `,
})
export class TextTranscriptComponent {
    readonly messages = input.required<readonly Pick<Message, 'id' | 'role' | 'content'>[]>();
    readonly label = input('Conversation');
    protected readonly speakers = {
        user: 'User',
        assistant: 'Assistant',
        system: 'System',
        tool: 'Tool',
    };
}

@Component({
    selector: 'threadplane-tool-observation',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `
    <section [attr.aria-label]="label()">
      <h3>{{ name() }}</h3>
      <dl>
        <dt>Arguments</dt>
        <dd>
          <pre>{{ argumentsText() }}</pre>
        </dd>
        @if (resultText() !== undefined) {
        <dt>Result</dt>
        <dd>
          <pre>{{ resultText() }}</pre>
        </dd>
        }
      </dl>
    </section>
  `,
    styles: `
    :host { display: block; color: var(--ds-text-primary, #142435); font-family: inherit; overflow-wrap: anywhere; }
    dl, dd { margin: 0; }
    dt { font-weight: 600; }
    pre { margin-block: .25rem; white-space: pre-wrap; overflow-wrap: anywhere; }
  `,
})
export class ToolObservationComponent {
    readonly name = input.required<string>();
    readonly argumentsText = input.required<string>();
    readonly resultText = input<string>();
    readonly label = input('Tool observation');
}

@Component({
    selector: 'threadplane-markdown-image',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `
    @if (url(); as destination) { @if (!failed()) {
    <img
      [src]="destination"
      [alt]="image().alt"
      [title]="image().title"
      (error)="failed.set(true)"
    />
    } @else {
    <span role="img" [attr.aria-label]="image().alt || 'Image unavailable'">{{
      image().alt || 'Image unavailable'
    }}</span>
    } } @else {
    <span role="img" [attr.aria-label]="image().alt || 'Image unavailable'">{{
      image().alt || 'Image unavailable'
    }}</span>
    }
  `,
})
export class MarkdownImageComponent {
    readonly image = input.required<Extract<MarkdownNode, {
        type: 'image';
    }>>();
    protected readonly failed = signal(false);
    protected url() {
        return markdownUrl(this.image().url, 'image');
    }
}

@Directive({ selector: 'ng-template[markdownNodes]', standalone: true })
export class MarkdownNodesDirective {
    static ngTemplateContextGuard(_directive: MarkdownNodesDirective, context: unknown): context is MarkdownContext {
        return true;
    }
}

@Directive({ selector: '[markdownOutlet]', standalone: true })
export class MarkdownOutletDirective implements OnChanges {
    readonly markdownOutlet = input.required<TemplateRef<MarkdownContext>>();
    readonly markdownContext = input.required<MarkdownContext>();
    private readonly container = inject(ViewContainerRef);
    private template: TemplateRef<MarkdownContext> | undefined;
    private view: EmbeddedViewRef<MarkdownContext> | undefined;
    ngOnChanges(): void {
        const template = this.markdownOutlet();
        const context = this.markdownContext();
        if (!this.view || this.template !== template) {
            this.container.clear();
            this.template = template;
            this.view = this.container.createEmbeddedView(template, { ...context });
        }
        else {
            Object.assign(this.view.context, context);
            this.view.markForCheck();
        }
    }
}

@Component({
    selector: 'threadplane-markdown',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [
        MarkdownNodesDirective,
        MarkdownOutletDirective,
        MarkdownImageComponent,
    ],
    template: `
    @for (document of [snapshot().document]; track document.generation) { @if
    (snapshot().root; as root) {
    <ng-container
      [markdownOutlet]="nodesView"
      [markdownContext]="{
        $implicit: root.children,
        root,
        anchor: false,
        header: false
      }"
    />
    } }
    <ng-template
      #nodesView
      markdownNodes
      let-nodes
      let-root="root"
      let-anchor="anchor"
      let-header="header"
    >
      @for (node of nodes; track node.type + ':' + node.id) { @switch
      (node.type) { @case ('document') {
      <ng-container
        [markdownOutlet]="nodesView"
        [markdownContext]="{
          $implicit: node.children,
          root: node,
          anchor,
          header
        }"
      />
      } @case ('paragraph') {
      <p>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </p>
      } @case ('heading') { @switch (node.level) { @case (1) {
      <h1>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </h1>
      } @case (2) {
      <h2>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </h2>
      } @case (3) {
      <h3>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </h3>
      } @case (4) {
      <h4>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </h4>
      } @case (5) {
      <h5>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </h5>
      } @case (6) {
      <h6>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </h6>
      } } } @case ('blockquote') {
      <blockquote>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </blockquote>
      } @case ('list') { @if (node.ordered) {
      <ol [attr.start]="node.start">
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </ol>
      } @else {
      <ul>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </ul>
      } } @case ('list-item') {
      <li>
        @if (node.task; as task) {
        <input
          type="checkbox"
          disabled
          [checked]="task.checked"
          [attr.aria-label]="
            task.checked ? 'Completed task' : 'Incomplete task'
          "
        />
        }
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </li>
      } @case ('code-block') {
      <pre><code>{{ node.text }}</code></pre>
      } @case ('thematic-break') {
      <hr />
      } @case ('text') {<ng-container>{{ node.text }}</ng-container
      >} @case ('emphasis') {
      <em
        ><ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{
            $implicit: node.children,
            root,
            anchor,
            header
          }"
      /></em>
      } @case ('strong') {
      <strong
        ><ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{
            $implicit: node.children,
            root,
            anchor,
            header
          }"
      /></strong>
      } @case ('strikethrough') {
      <del
        ><ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{
            $implicit: node.children,
            root,
            anchor,
            header
          }"
      /></del>
      } @case ('inline-code') {
      <code class="inline-code">{{ node.text }}</code> } @case ('link') { @if
      (!anchor && url(node.url, 'link'); as destination) {
      <a [href]="destination" [title]="node.title"
        ><ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{
            $implicit: node.children,
            root,
            anchor: true,
            header
          }"
      /></a>
      } @else {
      <ng-container
        [markdownOutlet]="nodesView"
        [markdownContext]="{ $implicit: node.children, root, anchor, header }"
      />
      } } @case ('autolink') { @if (!anchor && url(node.url, 'link'); as
      destination) { <a [href]="destination">{{ node.text }}</a> } @else
      {<ng-container>{{ node.text }}</ng-container
      >} } @case ('link-reference') { @if (node.resolved) { @if (!anchor &&
      url(node.url, 'link'); as destination) {
      <a [href]="destination" [title]="node.title"
        ><ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{
            $implicit: node.children,
            root,
            anchor: true,
            header
          }"
      /></a>
      } @else {
      <ng-container
        [markdownOutlet]="nodesView"
        [markdownContext]="{ $implicit: node.children, root, anchor, header }"
      />
      } } @else {<ng-container>[</ng-container
      ><ng-container
        [markdownOutlet]="nodesView"
        [markdownContext]="{ $implicit: node.children, root, anchor, header }"
      /><ng-container>{{ ']' + referenceSuffix(node) }}</ng-container
      >} } @case ('image') { @for (image of [node]; track image.url) {
      <threadplane-markdown-image [image]="image" /> } } @case ('soft-break')
      {<ng-container>{{ '\\n' }}</ng-container
      >} @case ('hard-break') { <br />
      } @case ('table') {
      <div
        class="tp-markdown__table-scroll"
        role="group"
        aria-label="Table"
        tabindex="0"
      >
        <table>
          <thead>
            <ng-container
              [markdownOutlet]="nodesView"
              [markdownContext]="{
                $implicit: tableRows(node, true),
                root,
                anchor,
                header: true
              }"
            />
          </thead>
          <tbody>
            <ng-container
              [markdownOutlet]="nodesView"
              [markdownContext]="{
                $implicit: tableRows(node, false),
                root,
                anchor,
                header: false
              }"
            />
          </tbody>
        </table>
      </div>
      } @case ('table-row') {
      <tr>
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{
            $implicit: node.children,
            root,
            anchor,
            header: node.isHeader
          }"
        />
      </tr>
      } @case ('table-cell') { @if (header) {
      <th [style.text-align]="node.alignment">
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </th>
      } @else {
      <td [style.text-align]="node.alignment">
        <ng-container
          [markdownOutlet]="nodesView"
          [markdownContext]="{ $implicit: node.children, root, anchor, header }"
        />
      </td>
      } } @case ('citation-reference') { @if (root.citations.get(node.refId); as
      citation) {
      <sup [attr.aria-label]="'Citation ' + citation.index">{{
        '[' + citation.index + ']'
      }}</sup>
      } @else {
      <sup [attr.aria-label]="'Unresolved citation ' + node.refId">{{
        '[^' + node.refId + ']'
      }}</sup>
      } } @case ('math-inline') {<ng-container>{{
        mathSource(node)
      }}</ng-container
      >} @case ('math-display') {
      <pre>{{ mathSource(node) }}</pre>
      } @case ('html-inline') {<ng-container>{{ node.raw }}</ng-container
      >} @case ('html-block') {
      <pre>{{ node.raw }}</pre>
      } } }
    </ng-template>
  `,
    styles: `
    :host {
      display: block;
      color: var(--ds-text-primary, #142435);
      font-family: inherit;
      white-space: pre-wrap;
      overflow-wrap: anywhere;
    }
    pre { white-space: pre-wrap; overflow-wrap: anywhere; }
    .inline-code { white-space: pre-wrap; }
    .tp-markdown__table-scroll { max-width: 100%; overflow-x: auto; }
    .tp-markdown__table-scroll:focus-visible { outline: 2px solid currentColor; outline-offset: -2px; }
  `,
})
export class MarkdownComponent {
    readonly snapshot = input.required<MarkdownSnapshot>();
    protected readonly url = markdownUrl;
    protected tableRows(node: Extract<MarkdownNode, {
        type: 'table';
    }>, header: boolean): readonly MarkdownNode[] {
        return node.children.filter((row) => row.isHeader === header);
    }
    protected referenceSuffix(node: Extract<MarkdownNode, {
        type: 'link-reference';
    }>): string {
        return node.form === 'full'
            ? '[' + node.label + ']'
            : node.form === 'collapsed'
                ? '[]'
                : '';
    }
    protected mathSource(node: Extract<MarkdownNode, {
        type: 'math-inline' | 'math-display';
    }>) {
        if (node.type === 'math-inline')
            return node.delimiter === '$'
                ? '$' + node.text + '$'
                : '\\(' + node.text + '\\)';
        return node.delimiter === '$$'
            ? '$$\n' + node.text + '\n$$'
            : '\\[' + node.text + '\\]';
    }
}

@Component({
    selector: 'chat-debug',
    standalone: true,
    imports: [TimelineInspectorComponent, StateInspectorComponent],
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [
        CHAT_DEBUG_TOKENS,
        `
      :host {
        display: contents;
      }

      /* ── Status pill launcher ─────────────────────────────────────── */
      .launcher {
        position: fixed;
        top: 20px;
        right: 20px;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 36px;
        height: 36px;
        border-radius: var(--tplane-chat-debug-radius-pill);
        background: var(--tplane-chat-debug-bg);
        border: 1px solid var(--tplane-chat-debug-border);
        color: var(--tplane-chat-debug-text);
        cursor: pointer;
        z-index: var(--tplane-chat-z-debug-pill, 990);
        box-shadow: var(--tplane-chat-debug-shadow-pill);
        transition: background var(--tplane-chat-motion-duration) var(--tplane-chat-motion-ease), border-color var(--tplane-chat-motion-duration) var(--tplane-chat-motion-ease);
        padding: 0;
      }
      .launcher:hover {
        background: var(--tplane-chat-debug-surface);
        border-color: var(--tplane-chat-debug-border-strong);
      }
      .launcher__dot {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background: var(--tplane-chat-debug-success);
        box-shadow: 0 0 8px
          color-mix(in srgb, var(--tplane-chat-debug-success) 60%, transparent);
      }
      .launcher__dot--streaming {
        background: var(--tplane-chat-debug-accent);
        box-shadow: 0 0 8px
          color-mix(in srgb, var(--tplane-chat-debug-accent) 70%, transparent);
        animation: chat-debug-pill-pulse 1.2s ease-in-out infinite;
      }
      @keyframes chat-debug-pill-pulse {
        0%,
        100% {
          opacity: 1;
          transform: scale(1);
        }
        50% {
          opacity: 0.6;
          transform: scale(0.85);
        }
      }

      /* ── Docked panel ─────────────────────────────────────────────── */
      .panel {
        position: fixed;
        background: var(--tplane-chat-debug-bg);
        color: var(--tplane-chat-debug-text);
        border: 1px solid var(--tplane-chat-debug-border);
        z-index: var(--tplane-chat-z-debug-panel, 991);
        display: flex;
        flex-direction: column;
        box-shadow: var(--tplane-chat-debug-shadow-panel);
        animation: chat-debug-panel-enter 120ms ease;
      }
      .panel--right {
        top: 0;
        right: var(--tplane-chat-sidebar-claim-right, 0);
        bottom: 0;
        width: var(--panel-size, 420px);
        border-right: 0;
        border-top-left-radius: var(--tplane-chat-debug-radius-panel);
        border-bottom-left-radius: var(--tplane-chat-debug-radius-panel);
        transform-origin: bottom right;
        transition: right var(--tplane-chat-motion-duration-slow) var(--tplane-chat-motion-ease);
      }
      .panel--left {
        top: 0;
        left: 0;
        bottom: 0;
        width: var(--panel-size, 420px);
        border-left: 0;
        border-top-right-radius: var(--tplane-chat-debug-radius-panel);
        border-bottom-right-radius: var(--tplane-chat-debug-radius-panel);
        transform-origin: bottom left;
      }
      .panel--bottom {
        left: 0;
        right: var(--tplane-chat-sidebar-claim-right, 0);
        bottom: 0;
        height: var(--panel-size, 40vh);
        border-bottom: 0;
        border-top-left-radius: var(--tplane-chat-debug-radius-panel);
        border-top-right-radius: var(--tplane-chat-debug-radius-panel);
        transform-origin: bottom right;
        transition: right var(--tplane-chat-motion-duration-slow) var(--tplane-chat-motion-ease);
      }
      /* Mobile breakpoint: when an edge-claimer occupies the right and
       the device is narrow, the bottom strip's effective width is
       ~zero. Explicitly hide it so it doesn't intercept pointer events
       on the sidebar drawer. The chat-debug launcher remains visible. */
      @media (max-width: 767px) {
        .panel--bottom {
          display: none;
        }
      }
      @keyframes chat-debug-panel-enter {
        from {
          opacity: 0;
          transform: scale(0.96);
        }
        to {
          opacity: 1;
          transform: scale(1);
        }
      }

      .panel__header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 12px 16px;
        border-bottom: 1px solid var(--tplane-chat-debug-border);
        min-height: 44px;
        box-sizing: border-box;
      }
      .panel__title {
        margin: 0;
        font-size: 13px;
        font-weight: 600;
        letter-spacing: -0.01em;
        color: var(--tplane-chat-debug-text);
      }
      .panel__actions {
        display: flex;
        align-items: center;
        gap: 4px;
      }

      .panel__dock-group {
        display: inline-flex;
        gap: 0;
        padding: 2px;
        background: var(--tplane-chat-debug-bg-deep);
        border: 1px solid var(--tplane-chat-debug-border);
        border-radius: var(--tplane-chat-radius-card);
      }
      .panel__dock-btn {
        appearance: none;
        background: transparent;
        border: 0;
        border-radius: var(--tplane-chat-radius-sm);
        width: 24px;
        height: 22px;
        padding: 0;
        color: var(--tplane-chat-debug-text-subtle);
        cursor: pointer;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transition: background var(--tplane-chat-motion-duration) var(--tplane-chat-motion-ease), color var(--tplane-chat-motion-duration) var(--tplane-chat-motion-ease);
      }
      .panel__dock-btn:hover {
        color: var(--tplane-chat-debug-text);
      }
      .panel__dock-btn.is-active {
        background: var(--tplane-chat-debug-border);
        color: var(--tplane-chat-debug-text);
      }
      .panel__dock-btn svg {
        display: block;
      }

      .panel__close {
        appearance: none;
        background: transparent;
        border: 0;
        border-radius: var(--tplane-chat-radius-card);
        width: 26px;
        height: 26px;
        margin-left: 4px;
        color: var(--tplane-chat-debug-text-subtle);
        cursor: pointer;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transition: background var(--tplane-chat-motion-duration) var(--tplane-chat-motion-ease), color var(--tplane-chat-motion-duration) var(--tplane-chat-motion-ease);
      }
      .panel__close:hover {
        background: var(--tplane-chat-debug-surface);
        color: var(--tplane-chat-debug-text);
      }

      .panel__controls {
        border-bottom: 1px solid var(--tplane-chat-debug-border);
        overflow-y: auto;
        max-height: 50%;
        background: var(--tplane-chat-debug-bg);
      }
      .panel__controls:empty {
        display: none;
      }

      .panel__tabs {
        display: flex;
        gap: 4px;
        border-bottom: 1px solid var(--tplane-chat-debug-border);
        padding: 0 12px;
        background: var(--tplane-chat-debug-bg);
      }
      .panel__tab {
        appearance: none;
        background: transparent;
        border: 0;
        border-bottom: 2px solid transparent;
        padding: 10px 8px;
        font: inherit;
        font-size: 13px;
        font-weight: 500;
        color: var(--tplane-chat-debug-text-muted);
        cursor: pointer;
        transition: color var(--tplane-chat-motion-duration) var(--tplane-chat-motion-ease), border-color var(--tplane-chat-motion-duration) var(--tplane-chat-motion-ease);
        margin-bottom: -1px;
      }
      .panel__tab:hover {
        color: var(--tplane-chat-debug-text);
      }
      .panel__tab.is-active {
        color: var(--tplane-chat-debug-text);
        border-bottom-color: var(--tplane-chat-debug-accent);
      }

      .panel__body {
        flex: 1;
        min-height: 0;
        overflow: hidden;
        display: flex;
        flex-direction: column;
        background: var(--tplane-chat-debug-bg);
      }
    `,
    ],
    template: `
    @if (!open() && launcher() === 'floating') {
    <button
      type="button"
      class="launcher"
      title="Open chat devtools"
      aria-label="Open chat devtools"
      [attr.aria-pressed]="false"
      (click)="setOpen(true)"
    >
      <span
        class="launcher__dot"
        [class.launcher__dot--streaming]="isStreaming()"
        aria-hidden="true"
      ></span>
    </button>
    } @else if (open() && agent(); as currentAgent) {
    <div
      class="panel"
      [class.panel--right]="dockState() === 'right'"
      [class.panel--bottom]="dockState() === 'bottom'"
      [class.panel--left]="dockState() === 'left'"
      role="region"
      aria-label="Chat devtools"
    >
      <div class="panel__header">
        <h3 class="panel__title">Chat Devtools</h3>
        <div class="panel__actions">
          <div
            class="panel__dock-group"
            role="group"
            aria-label="Dock position"
          >
            <button
              type="button"
              class="panel__dock-btn"
              [class.is-active]="dockState() === 'left'"
              (click)="setDock('left')"
              aria-label="Dock left"
            >
              <svg
                width="14"
                height="14"
                viewBox="0 0 14 14"
                fill="none"
                stroke="currentColor"
                stroke-width="1.5"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <rect x="1.5" y="2.5" width="11" height="9" rx="1.2" />
                <line x1="5.5" y1="2.5" x2="5.5" y2="11.5" />
              </svg>
            </button>
            <button
              type="button"
              class="panel__dock-btn"
              [class.is-active]="dockState() === 'bottom'"
