        top: number;
        left: number;
    }>(() => {
        if (!this.open())
            return { top: 0, left: 0 };
        const pos = this.anchorPos();
        if (pos) {
            return { top: pos.y + 4, left: Math.max(pos.x, 8) };
        }
        const el = this.anchor();
        if (!el) {
            const vw = typeof window === 'undefined' ? 0 : window.innerWidth;
            const vh = typeof window === 'undefined' ? 0 : window.innerHeight;
            return { top: Math.max(vh / 3, 0), left: Math.max(vw / 2 - 80, 0) };
        }
        const rect = el.getBoundingClientRect();
        return { top: rect.bottom + 4, left: Math.max(rect.right - 160, 8) };
    });
    constructor() {
        effect(() => {
            if (!this.open())
                return;
            queueMicrotask(() => {
                const root = document.querySelector('.chat-overflow-menu');
                const first = root?.querySelector<HTMLElement>('.chat-overflow-menu__item:not(.chat-overflow-menu__item--disabled)');
                first?.focus();
            });
        });
    }
    protected onItemClick(item: OverflowMenuItem): void {
        if (item.disabled)
            return;
        this.itemSelected.emit(item.id);
        this.closed.emit();
    }
    protected onMenuKeydown(e: KeyboardEvent): void {
        if (e.key === 'Escape') {
            e.preventDefault();
            this.closed.emit();
            return;
        }
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
            e.preventDefault();
            const root = (e.currentTarget as HTMLElement);
            const items = Array.from(root.querySelectorAll<HTMLElement>('.chat-overflow-menu__item:not(.chat-overflow-menu__item--disabled)'));
            if (items.length === 0)
                return;
            const current = document.activeElement as HTMLElement | null;
            const idx = current ? items.indexOf(current) : -1;
            const next = e.key === 'ArrowDown'
                ? Math.min((idx < 0 ? 0 : idx + 1), items.length - 1)
                : Math.max(idx - 1, 0);
            items[next]?.focus();
        }
    }
}

@Component({
    selector: 'chat-project-list',
    standalone: true,
    imports: [ChatOverflowMenuComponent, ChatConfirmDialogComponent],
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [CHAT_HOST_TOKENS, CHAT_PROJECT_LIST_STYLES],
    template: `
    @if (showNewProjectButton()) {
      <button type="button" class="chat-project-list__new" (click)="onNewProjectClicked()">+ New project</button>
    }
    <ul class="chat-project-list">
      @if (creatingProject()) {
        <li class="chat-project-list__item-wrap">
          <input
            #createInput
            class="chat-project-list__edit"
            type="text"
            placeholder="New project name"
            [value]="creatingValue()"
            (input)="onCreateInput($event)"
            (keydown.enter)="commitCreate()"
            (keydown.escape)="cancelCreate()"
            (blur)="cancelCreate()"
            aria-label="New project name"
          />
        </li>
      }
      @for (project of visibleProjects(); track project.id) {
        <li class="chat-project-list__item-wrap">
          @if (editingProjectId() === project.id) {
            <input
              #editInput
              class="chat-project-list__edit"
              type="text"
              [value]="editingValue()"
              (input)="onEditInput($event)"
              (keydown.enter)="commitRename(project.id)"
              (keydown.escape)="cancelRename()"
              (blur)="cancelRename()"
              aria-label="Rename project"
            />
          } @else {
            <button
              type="button"
              class="chat-project-list__item"
              [attr.data-active]="project.id === activeProjectId() ? 'true' : null"
              [attr.aria-current]="project.id === activeProjectId() ? 'true' : null"
              (click)="selectProject(project.id)"
            >{{ project.name }}</button>

            @if (showKebab()) {
              <button
                #kebab
                type="button"
                class="chat-project-list__kebab"
                aria-label="More actions"
                aria-haspopup="menu"
                [attr.aria-expanded]="menuOpenForId() === project.id ? 'true' : 'false'"
                (click)="openMenu(project.id, kebab)"
              >⋯</button>
            }
          }
        </li>
      }
    </ul>

    <chat-overflow-menu
      [open]="menuOpenForId() !== null"
      [items]="currentMenuItems()"
      [anchor]="menuAnchor()"
      (itemSelected)="onMenuAction($event)"
      (closed)="menuOpenForId.set(null)"
    />

    <chat-confirm-dialog
      [open]="confirmDeleteId() !== null"
      title="Delete project?"
      body="The project will be deleted. Threads in this project will remain but become unassigned."
      confirmLabel="Delete"
      tone="destructive"
      (confirmed)="performDelete()"
      (cancelled)="confirmDeleteId.set(null)"
    />
  `,
})
export class ChatProjectListComponent {
    readonly projects = input.required<Project[]>();
    readonly activeProjectId = input<string | null>(null);
    readonly showNewProjectButton = input<boolean>(false);
    readonly actions = input<ProjectActionAdapter | null>(null);
    readonly projectSelected = output<string>();
    readonly newProjectRequested = output<void>();
    protected readonly creatingProject = signal<boolean>(false);
    protected readonly creatingValue = signal<string>('');
    protected readonly editingProjectId = signal<string | null>(null);
    protected readonly editingValue = signal<string>('');
    protected readonly menuOpenForId = signal<string | null>(null);
    protected readonly menuAnchor = signal<HTMLElement | null>(null);
    protected readonly confirmDeleteId = signal<string | null>(null);
    private readonly pendingHidden = signal<ReadonlySet<string>>(new Set());
    private readonly pendingRenames = signal<ReadonlyMap<string, string>>(new Map());
    protected readonly visibleProjects = computed<Project[]>(() => {
        const hidden = this.pendingHidden();
        const renames = this.pendingRenames();
        return this.projects()
            .filter((p) => !hidden.has(p.id))
            .map((p) => (renames.has(p.id) ? ({ ...p, name: renames.get(p.id)! }) : p));
    });
    protected readonly currentMenuItems = computed<OverflowMenuItem[]>(() => {
        const id = this.menuOpenForId();
        if (!id)
            return [];
        const a = this.actions();
        if (!a)
            return [];
        const items: OverflowMenuItem[] = [];
        if (a.rename)
            items.push({ id: 'rename', label: 'Rename' });
        if (a.delete)
            items.push({ id: 'delete', label: 'Delete', tone: 'destructive' });
        return items;
    });
    private readonly createInput = viewChild<ElementRef<HTMLInputElement>>('createInput');
    private readonly editInput = viewChild<ElementRef<HTMLInputElement>>('editInput');
    constructor() {
        effect(() => {
            if (this.creatingProject()) {
                queueMicrotask(() => this.createInput()?.nativeElement.focus());
            }
        });
    }
    protected selectProject(projectId: string): void {
        this.projectSelected.emit(projectId);
    }
    protected showKebab(): boolean {
        const a = this.actions();
        if (!a)
            return false;
        return Boolean(a.rename || a.delete);
    }
    protected openMenu(projectId: string, anchor: HTMLElement): void {
        this.menuAnchor.set(anchor);
        this.menuOpenForId.set(projectId);
    }
    protected onMenuAction(id: string): void {
        const projectId = this.menuOpenForId();
        this.menuOpenForId.set(null);
        if (!projectId)
            return;
        if (id === 'rename') {
            const p = this.projects().find((x) => x.id === projectId);
            this.editingValue.set(p?.name ?? '');
            this.editingProjectId.set(projectId);
            queueMicrotask(() => this.editInput()?.nativeElement.focus());
        }
        else if (id === 'delete') {
            this.confirmDeleteId.set(projectId);
        }
    }
    protected onNewProjectClicked(): void {
        this.creatingValue.set('');
        this.creatingProject.set(true);
        this.newProjectRequested.emit();
    }
    protected onCreateInput(e: Event): void {
        this.creatingValue.set((e.target as HTMLInputElement).value);
    }
    protected cancelCreate(): void {
        this.creatingProject.set(false);
        this.creatingValue.set('');
    }
    protected async commitCreate(): Promise<void> {
        const name = this.creatingValue().trim();
        this.creatingProject.set(false);
        this.creatingValue.set('');
        if (!name)
            return;
        const a = this.actions();
        if (!a?.create)
            return;
        try {
            await a.create(name);
        }
        catch { }
    }
    protected onEditInput(e: Event): void {
        this.editingValue.set((e.target as HTMLInputElement).value);
    }
    protected cancelRename(): void {
        this.editingProjectId.set(null);
    }
    protected async commitRename(projectId: string): Promise<void> {
        const newName = this.editingValue().trim();
        this.editingProjectId.set(null);
        if (!newName)
            return;
        const a = this.actions();
        if (!a?.rename)
            return;
        this.pendingRenames.update((m) => {
            const n = new Map(m);
            n.set(projectId, newName);
            return n;
        });
        try {
            await a.rename(projectId, newName);
        }
        catch {
        }
        finally {
            this.pendingRenames.update((m) => {
                const n = new Map(m);
                n.delete(projectId);
                return n;
            });
        }
    }
    protected async performDelete(): Promise<void> {
        const projectId = this.confirmDeleteId();
        this.confirmDeleteId.set(null);
        if (!projectId)
            return;
        const a = this.actions();
        if (!a?.delete)
            return;
        this.pendingHidden.update((s) => new Set([...s, projectId]));
        try {
            await a.delete(projectId);
        }
        catch {
        }
        finally {
            this.pendingHidden.update((s) => {
                const n = new Set(s);
                n.delete(projectId);
                return n;
            });
        }
    }
}

@Component({
    selector: 'chat-reasoning',
    standalone: true,
    imports: [ChatStreamingMdComponent],
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [CHAT_HOST_TOKENS, CHAT_REASONING_STYLES],
    host: {
        '[attr.data-has-content]': 'hasContent()',
        '[attr.data-expanded]': 'expandedStr()',
        '[attr.data-streaming]': 'isStreaming()',
    },
    template: `
    <button
      type="button"
      class="chat-reasoning__header"
      [attr.aria-expanded]="expanded()"
      (click)="toggle()"
    >
      <svg class="chat-reasoning__chevron" viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
        <path d="M4 2l4 4-4 4"/>
      </svg>
      @if (isStreaming()) {
        <span class="chat-reasoning__pulse" aria-hidden="true"></span>
      }
      <span class="chat-reasoning__label">{{ resolvedLabel() }}</span>
    </button>
    @if (expanded()) {
      <div class="chat-reasoning__body">
        <chat-streaming-md [document]="document()" />
      </div>
    }
  `,
})
export class ChatReasoningComponent {
    readonly content = input<string>('');
    readonly delivery = input.required<MessageDelivery>();
    readonly durationMs = input<number | undefined>(undefined);
    readonly label = input<string | undefined>(undefined);
    readonly defaultExpanded = input<boolean>(false);
    readonly hasContent = computed(() => (this.content() ?? '').length > 0);
    readonly isStreaming = computed(() => this.delivery().phase === 'streaming');
    readonly document = computed(() => markdownDocument(this.content(), this.delivery(), ':reasoning'));
    private readonly _expandedOverride = signal<boolean | null>(null);
    readonly expanded = computed(() => {
        const override = this._expandedOverride();
        if (override !== null)
            return override;
        if (this.isStreaming())
            return true;
        return this.defaultExpanded();
    });
    readonly expandedStr = computed(() => String(this.expanded()));
    readonly resolvedLabel = computed(() => {
        const explicit = this.label();
        if (explicit)
            return explicit;
        if (this.isStreaming())
            return 'Thinking…';
        const ms = this.durationMs();
        if (typeof ms === 'number')
            return `Thought for ${formatDuration(ms)}`;
        return 'Show reasoning';
    });
    constructor() {
        let prevStreaming = false;
        effect(() => {
            const streaming = this.isStreaming();
            if (!prevStreaming && streaming) {
                this._expandedOverride.set(null);
            }
            prevStreaming = streaming;
        });
    }
    toggle(): void {
        this._expandedOverride.set(!this.expanded());
    }
}

