export class FakeAgent extends AbstractAgent {
    private readonly tokens: string[];
    private readonly reasoningTokens: string[];
    private readonly delayMs: number;
    private readonly script: FakeAgentScript;
    constructor(opts: {
        tokens?: string[];
        reasoningTokens?: string[];
        delayMs?: number;
        script?: FakeAgentScript;
    } = {}) {
        super();
        this.tokens = opts.tokens ?? [
            'Hello', ' from', ' the', ' fake', ' AG-UI', ' agent.',
            ' This', ' is', ' a', ' canned', ' streaming', ' reply.',
        ];
        this.reasoningTokens = opts.reasoningTokens ?? [];
        this.delayMs = opts.delayMs ?? 60;
        this.script = opts.script ?? [];
    }
    run(input: RunAgentInput): Observable<BaseEvent> {
        const scripted = this.scriptedSequence(input);
        if (scripted)
            return this.emitSequence(scripted, 30);
        const tokens = this.tokens;
        const reasoningTokens = this.reasoningTokens;
        const messageId = `fake-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
        const sequence: BaseEvent[] = [
            { type: EventType.RUN_STARTED, threadId: input.threadId, runId: input.runId } as BaseEvent,
        ];
        if (reasoningTokens.length > 0) {
            sequence.push({ type: EventType.REASONING_MESSAGE_START, messageId, role: 'assistant' } as BaseEvent);
            for (const delta of reasoningTokens) {
                sequence.push({ type: EventType.REASONING_MESSAGE_CONTENT, messageId, delta } as BaseEvent);
            }
            sequence.push({ type: EventType.REASONING_MESSAGE_END, messageId } as BaseEvent);
        }
        sequence.push({ type: EventType.TEXT_MESSAGE_START, messageId, role: 'assistant' } as BaseEvent);
        for (const delta of tokens) {
            sequence.push({ type: EventType.TEXT_MESSAGE_CONTENT, messageId, delta } as BaseEvent);
        }
        sequence.push({ type: EventType.TEXT_MESSAGE_END, messageId } as BaseEvent);
        sequence.push({ type: EventType.RUN_FINISHED, threadId: input.threadId, runId: input.runId } as BaseEvent);
        return this.emitSequence(sequence, 30);
    }
    private scriptedSequence(input: RunAgentInput): BaseEvent[] | undefined {
        if (this.script.length === 0)
            return undefined;
        const branch = this.script.find((candidate) => matchesBranch(candidate.when, input));
        if (!branch)
            return undefined;
        return [
            { type: EventType.RUN_STARTED, threadId: input.threadId, runId: input.runId } as BaseEvent,
            ...branch.events,
            { type: EventType.RUN_FINISHED, threadId: input.threadId, runId: input.runId } as BaseEvent,
        ];
    }
    private emitSequence(sequence: readonly BaseEvent[], initialDelayMs: number): Observable<BaseEvent> {
        const delayMs = this.delayMs;
        return new Observable<BaseEvent>((observer) => {
            let cancelled = false;
            let timer: ReturnType<typeof setTimeout> | undefined;
            let i = 0;
            const emitNext = () => {
                if (cancelled)
                    return;
                if (i >= sequence.length) {
                    observer.complete();
                    return;
                }
                observer.next(sequence[i]);
                i++;
                timer = setTimeout(emitNext, delayMs);
            };
            timer = setTimeout(emitNext, initialDelayMs);
            return () => {
                cancelled = true;
                if (timer !== undefined)
                    clearTimeout(timer);
            };
        });
    }
}

export type FakeAgentScript = readonly {
    when: 'initial' | {
        toolMessageFor: string;
    };
    events: readonly BaseEvent[];
}[];

export interface HttpReplayOptions {
    url: (threadId: string) => string;
    fetch?: typeof fetch;
    headers?: Record<string, string>;
}

export interface InterruptSessionSnapshot {
    phase: InterruptSessionPhase;
    generation: number;
    interrupts: Interrupt[];
    legacy?: AgentInterrupt;
    runId?: string;
    attempt?: ResumeAttempt;
}

export interface ResumeAttempt {
    id: string;
    runId: string;
    input: AgentSubmitInput;
    parameters: {
        resume?: ResumeEntry[];
        forwardedProps?: Record<string, unknown>;
    };
    generation: number;
}

export interface ThreadSnapshot {
    state: Record<string, unknown>;
    messages: Message[];
}

export interface ToAgentOptions {
    persistence?: AgUiInterruptPersistence;
    interruptTransport?: InterruptTransport;
    replay?: AgUiReplaySource;
    telemetry?: AgentRuntimeTelemetrySink | false;
    a2uiClientCapabilities?: {
        supportedCatalogIds: string[];
        inlineCatalogs?: unknown[];
    };
}

export function bridgeCitationsState(thread: ThreadStateLike, messages: Message[]): Message[] {
    const citationsByMsg = (thread.state as {
        citations?: unknown;
    })?.citations;
    if (!citationsByMsg || typeof citationsByMsg !== 'object')
        return messages;
    const map = citationsByMsg as Record<string, unknown>;
    return messages.map(msg => {
        const raw = map[msg.id];
        if (!Array.isArray(raw) || raw.length === 0)
            return msg;
        return { ...msg, citations: raw.map((entry, i) => normalizeCitation(entry, i + 1)) };
    });
}

export function httpReplay(options: HttpReplayOptions): AgUiReplaySource {
    return async (threadId, signal) => {
        const fetchImpl = options.fetch ?? globalThis.fetch.bind(globalThis);
        const response = await fetchImpl(options.url(threadId), {
            method: 'GET',
            headers: { accept: 'application/json', ...options.headers },
            signal,
        });
        if (response.status === 404)
            return [];
        if (!response.ok)
            throw new Error(`Thread replay request failed with status ${response.status}`);
        const body: unknown = await response.json();
        if (!isRecord(body) || !Array.isArray(body['events'])) {
            throw new Error('Thread replay response must be a JSON object with an events array');
        }
        const events = body['events'] as unknown[];
        for (const event of events) {
            if (!isRecord(event) || typeof event['type'] !== 'string') {
                throw new Error('Thread replay events must be objects with a string type');
            }
        }
        return events as BaseEvent[];
    };
}

export function injectAgent<T>(ref?: AgentRef<T>): AgUiAgent<T> {
    return inject(ref ? ref.token : AGENT) as AgUiAgent<T>;
}

export function provideAgent<T = Record<string, unknown>>(refOrConfig: AgentRef<T> | AgentConfig | (() => AgentConfig), maybeConfig?: AgentConfig | (() => AgentConfig)): Provider[] {
    const ref = isAgentRef<T>(refOrConfig) ? refOrConfig : undefined;
    const configOrFactory = (ref ? maybeConfig : refOrConfig) as AgentConfig | (() => AgentConfig);
    if (!ref) {
        return [{ provide: AGENT, useFactory: () => buildAgUiAgent(configOrFactory) }];
    }
    return [
        { provide: AGENT_REF_DEBUG_NAMES, multi: true, useValue: refDebugName(ref) },
        {
            provide: ref.token,
            useFactory: () => {
                warnOnAmbiguousSharedAlias();
                return buildAgUiAgent(configOrFactory);
            },
        },
        { provide: AGENT, useExisting: ref.token },
    ];
}

export function provideFakeAgent(config: AgUiFakeAgentConfig = {}): Provider[] {
    return [
        {
            provide: AGENT,
            useFactory: () => {
                const adapter = toAgent(new FakeAgent(config));
                inject(DestroyRef).onDestroy(() => adapter.dispose());
                return adapter;
            },
        },
    ];
}

export function toAgent(source: AbstractAgent, options: ToAgentOptions = {}): AgUiAgent {
    return createAgentAdapter(source, options);
}

