          <ng-container ngProjectAs="[chatInputFooter]">
            <ng-container [ngTemplateOutlet]="inputFooter" />
          </ng-container>
        </chat-input>
        <ng-container ngProjectAs="[chatWelcomeSuggestions]">
          <ng-container [ngTemplateOutlet]="welcomeSuggestions" />
        </ng-container>
      </chat-welcome>
    } @else {
    <div class="chat-shell">
      @if (threads().length > 0) {
        <aside class="chat-shell__sidebar">
          <chat-thread-list
            [threads]="threads()"
            [activeThreadId]="activeThreadId()"
            (threadSelected)="threadSelected.emit($event)"
          />
        </aside>
      }
      <div class="chat-shell__main">
        <chat-window>
          <ng-content select="[chatHeader]" chatHeader />
          <!-- A named region the keyboard can focus and scroll: a long reply
               with no links holds no other tab stop to scroll it into view. -->
          <div chatBody class="chat-scroll" #scrollContainer (scroll)="onScroll($event)"
               role="region" aria-label="Conversation" tabindex="0">
            @let currentActivityTemplate = activityTemplate();
            @let currentExcludedToolNames = currentActivityTemplate ? [] : excludedToolNames();
            @let currentToolCallTemplates = currentActivityTemplate ? [] : toolCallTemplates();
            @let currentToolResultTemplates = currentActivityTemplate ? [] : toolResultTemplates();
            @let currentGroupRelatedTools = groupRelatedTools();
            @let currentToolLabel = toolLabel();
            @let currentToolOutcome = toolOutcome();
            @let currentViews = effectiveViews();
            @let currentStore = resolvedStore();
            @let currentHandlers = handlers();
            @if (currentMessages.length === 0) {
              <ng-container [ngTemplateOutlet]="welcomeSuggestions" />
            }
            <chat-message-list [agent]="currentAgent">
              <ng-template chatMessageTemplate="human" let-message let-i="index">
                <chat-message [role]="'user'" [prevRole]="previousRole(currentMessages, i)">{{ humanContent(message) }}</chat-message>
              </ng-template>

              <ng-template chatMessageTemplate="ai" let-message let-i="index">
                @let body = ownedMarkdownBodyFor(message.id);
                @let presentation = ownedMarkdownPresentationFor(message.id);
                @let content = presentation.content;
                <chat-message
                  [chatOwnedMarkdownContext]="body"
                  [role]="'assistant'"
                  [message]="message"
                  [prevRole]="previousRole(currentMessages, i)"
                  [streaming]="message.delivery.phase === 'streaming'"
                  [current]="i === currentMessages.length - 1"
                >
                  <ng-container ngProjectAs="[chatBeforeMarkdown]">
                  <!-- A projected chatActivityTemplate owns the reasoning +
                       tool-call region for this message. It renders at
                       message level (never inside a clipped trace body). -->
                  @if (currentActivityTemplate; as activity) {
                    <ng-container
                      [ngTemplateOutlet]="activity.templateRef"
                      [ngTemplateOutletContext]="activityContextFor(message, i)"
                    />
                  } @else {
                    <!-- Reasoning is merged across a run of consecutive (tool-
                         separated) reasoning steps and rendered ONCE at the run's
                         first step as "Thought for {total} · {N} steps", so a
                         multi-step agent shows one compact pill instead of a
                         stack of "Thought for 1s" chips. Single-step turns render
                         a normal "Thought for {duration}" pill. -->
                    @if (message.reasoning && reasoningRunStart(i)) {
                      @let run = reasoningRun(i);
                      <chat-reasoning
                        [content]="run.content"
                        [delivery]="run.delivery"
                        [durationMs]="run.durationMs"
                        [label]="run.label"
                      />
                    }
                    <!-- Per-tool templates projected into <chat> are collected
                         here and handed down as an input: a content query on
                         <chat-tool-calls> cannot see templates re-projected
                         through <chat>'s own ng-content. -->
                    <chat-tool-calls
                      [agent]="currentAgent"
                      [message]="message"
                      [excludeToolNames]="currentExcludedToolNames"
                      [toolCallTemplates]="currentToolCallTemplates"
                      [toolResultTemplates]="currentToolResultTemplates"
                      [groupRelated]="currentGroupRelatedTools"
                      [toolLabel]="currentToolLabel"
                      [toolOutcome]="currentToolOutcome"
                      (toolRetry)="toolRetry.emit($event)"
                    />
                  }
                  <chat-tool-views
                    [agent]="currentAgent"
                    [message]="message"
                    [views]="currentViews"
                    [store]="currentStore"
                    [handlers]="currentHandlers"
                    (events)="onClientToolEvent($event)"
                  />
                  </ng-container>
                  <ng-container ngProjectAs="[chatAfterMarkdown]">
                  @if (presentation.spec; as spec) {
                    <!-- Pass ONLY the explicit consumer store (may be
                         undefined) — never the conversation-wide internal
