                    this.classifiers.delete(key);
                }
            }
            for (const key of [...this.markdownDocuments.keys()]) {
                if (!liveIds.has(key))
                    this.markdownDocuments.delete(key);
            }
            for (const key of [...this.ownedMarkdownBodies.keys()]) {
                if (!liveIds.has(key))
                    this.removeOwnedMarkdownBody(key);
            }
            for (const key of [...this.activityContexts.keys()]) {
                if (!liveIds.has(key))
                    this.activityContexts.delete(key);
            }
        });
    }
    prevRole(index: number): ChatMessageRole | undefined {
        if (index === 0)
            return undefined;
        return this.previousRole(this.agent().messages(), index);
    }
    protected previousRole(messages: readonly Message[], index: number): ChatMessageRole | undefined {
        if (index === 0)
            return undefined;
        const prev = messages[index - 1];
        if (!prev)
            return undefined;
        const role = (prev as unknown as {
            role?: string;
        }).role;
        if (role === 'user')
            return 'user';
        if (role === 'assistant')
            return 'assistant';
        if (role === 'system')
            return 'system';
        if (role === 'tool')
            return 'tool';
        return undefined;
    }
    protected onScroll(event?: Event): void {
        const el = this.scrollContainer()?.nativeElement;
        if (!el || (event && event.target !== el))
            return;
        const intent = this.upwardWheel;
        if (intent && !intent.settled)
            return;
        const userScrolledUp = intent && intent.supported && el.scrollTop < intent.scrollTop;
        if (intent && el.scrollTop !== intent.scrollTop)
            this.upwardWheel = undefined;
        if (this.programmaticScrollCount > 0 && !userScrolledUp)
            return;
        const nextPinned = isPinned(el.scrollHeight, el.scrollTop, el.clientHeight, ChatComponent.PIN_TOLERANCE_PX);
        if (nextPinned !== this.pinned())
            this.pinned.set(nextPinned);
    }
    scrollToBottom(): void {
        this.upwardWheel = undefined;
        const el = this.scrollContainer()?.nativeElement;
        if (!el)
            return;
        this.programmaticScrollCount++;
        el.scrollTop = el.scrollHeight;
        this.programmaticScrollTop = el.scrollTop;
        requestAnimationFrame(() => { this.programmaticScrollCount--; });
        this.pinned.set(true);
    }
    private followIfPinned(): void {
        if (!untracked(() => this.pinned()))
            return;
        const el = this.scrollContainer()?.nativeElement;
        if (!el)
            return;
        const intent = this.upwardWheel;
        if (intent && el.scrollTop < intent.scrollTop) {
            if (!intent.settled) {
                intent.followDeferred = true;
                return;
            }
            this.onScroll();
            if (!untracked(() => this.pinned()))
                return;
        }
        this.programmaticScrollCount++;
        el.scrollTop = el.scrollHeight;
        this.programmaticScrollTop = el.scrollTop;
        if (intent && this.upwardWheel === intent)
            intent.scrollTop = this.programmaticScrollTop;
        requestAnimationFrame(() => { this.programmaticScrollCount--; });
    }
    protected onUserStopped(): void {
        if (typeof (this.agent() as {
            stop?: unknown;
        }).stop !== 'function')
            return;
        const users = this.agent().messages().filter((m) => m.role === 'user');
        const prompt = users[users.length - 1];
        this.stoppedTurn.set(prompt ? { userCount: users.length, prompt: messageContent(prompt) } : null);
    }
    protected onWelcomeFocusOut(event: FocusEvent): void {
        onFocusMovedAway(event, () => { this.welcomeHadFocus = false; });
    }
    protected onErrorFocusOut(event: FocusEvent): void {
        onFocusMovedAway(event, () => { this.errorHadFocus = false; });
    }
    protected isKeyboardFocus(event: FocusEvent): boolean {
        return matchesFocusVisible(event.target);
    }
    private continueInComposer(): void {
        requestAnimationFrame(() => {
            const active = this.composerDocument.activeElement;
            if (!active || active === this.composerDocument.body)
                this.composer()?.focusTextarea();
        });
    }
    protected onScrollBubbleClick(): void {
        const active = this.composerDocument.activeElement;
        const fromKeyboard = !!active?.closest('chat-scroll-bubble') && matchesFocusVisible(active);
        this.scrollToBottom();
        if (fromKeyboard)
            this.continueInComposer();
    }
    protected onUserSubmitted(): void {
        this.upwardWheel = undefined;
        this.pinned.set(true);
        this.recordSubmit();
    }
    submitMessage(text: string): void {
        const trimmed = text.trim();
        if (!trimmed || this.agent().isInputBlocked?.())
            return;
        void this.agent().submit({ message: trimmed });
        this.recordSubmit();
    }
    clearThread(): void {
        this.clearClassifiers();
        this.lifecycle._internal.messageCount.set(0);
        this.lifecycle._internal.inputSubmittedAt.set(null);
    }
    private recordSubmit(): void {
        if (!this.lifecycle._internal.firstMessageSent()) {
            this.lifecycle._internal.firstMessageSent.set(true);
        }
        this.lifecycle._internal.messageCount.update((c) => c + 1);
        this.lifecycle._internal.inputSubmittedAt.set(Date.now());
    }
    protected prevMessage(index: number): unknown {
        if (index === 0)
            return undefined;
        return this.agent().messages()[index - 1];
    }
    protected isGenuiTurn(message: unknown, _prevMsg: unknown, index?: number): boolean {
        const names = new Set(this.genuiToolNames());
        const m = message as {
            extra?: Record<string, unknown>;
        } | null | undefined;
        if (!m)
            return false;
        const calls = (m.extra?.['tool_calls'] as Array<{
            name?: string;
        }> | undefined) ?? [];
        if (calls.some(c => c.name != null && names.has(c.name)))
            return true;
        const rawContent = m.extra?.['content'];
        if (Array.isArray(rawContent)) {
            for (const block of rawContent) {
                if (block != null
                    && typeof block === 'object'
                    && (block as {
                        type?: unknown;
                    }).type === 'function_call'
                    && typeof (block as {
                        name?: unknown;
                    }).name === 'string'
                    && names.has((block as {
                        name: string;
                    }).name)) {
                    return true;
                }
            }
        }
        const projectedContent = (m as {
            content?: unknown;
        }).content;
        if (typeof projectedContent === 'string' && projectedContent.length > 0) {
            if (projectedContent.includes('"createSurface"')
                || projectedContent.includes('"updateComponents"')
                || projectedContent.includes('"updateDataModel"')) {
                return true;
            }
            if (projectedContent.includes('"root"') && projectedContent.includes('"elements"')) {
                return true;
            }
        }
        const p = _prevMsg as {
            role?: string;
            name?: string;
            extra?: Record<string, unknown>;
        } | null | undefined;
        if (p && p.role === 'tool') {
            const toolName = (p.extra?.['name'] as string | undefined) ?? p.name;
            if (typeof toolName === 'string' && names.has(toolName))
                return true;
        }
        if (typeof index === 'number' && index > 0) {
            const msgs = this.agent().messages();
            for (let i = index - 1; i >= 0; i--) {
                const prev = msgs[i] as {
                    role?: string;
                    extra?: Record<string, unknown>;
                };
                if (!prev)
                    break;
                if (prev.role === 'user')
                    break;
                const prevCalls = (prev.extra?.['tool_calls'] as Array<{
                    name?: string;
                }> | undefined) ?? [];
                if (prevCalls.some(c => c.name != null && names.has(c.name)))
                    return true;
                const prevRaw = prev.extra?.['content'];
                if (Array.isArray(prevRaw)) {
                    for (const block of prevRaw) {
                        if (block != null
                            && typeof block === 'object'
                            && (block as {
                                type?: unknown;
                            }).type === 'function_call'
                            && typeof (block as {
                                name?: unknown;
                            }).name === 'string'
                            && names.has((block as {
                                name: string;
                            }).name)) {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
    protected reconcileOwnedMarkdownBodies(agent: Agent, messages: ReturnType<Agent['messages']>): ReturnType<Agent['messages']> {
        untracked(() => this.reconcileOwnedMarkdownRows(agent, messages));
        return messages;
    }
    private reconcileOwnedMarkdownRows(agent: Agent, messages: readonly Message[]): void {
        if (this.ownedMarkdownAgent !== agent) {
            this.clearClassifiers();
            this.ownedMarkdownAgent = agent;
        }
        const liveIds = new Set<string>();
        for (const message of messages) {
            if (getMessageType(message) !== 'ai')
                continue;
            liveIds.add(message.id);
            const content = messageContent(message);
            const generation = message.delivery.generation;
            let entry = this.ownedMarkdownBodies.get(message.id);
            if (!entry) {
                const classifier = signal(this.classifyMessage(content, message));
                const contentSignal = signal(content);
                const delivery = signal<Pick<Message, 'id' | 'delivery'>>({ id: message.id, delivery: { ...message.delivery } });
                const document = computed(() => {
                    const markdown = classifier().markdown();
                    return markdown ? this.markdownDocumentFor(markdown, delivery()) : null;
                });
                entry = {
                    context: {
                        classifier, content: contentSignal, document,
                        presentation: this.ownedMarkdownPresentation(content, classifier()),
                    },
                    classifier, content: contentSignal, delivery, generation, classifiedContent: content,
                };
                this.ownedMarkdownBodies.set(message.id, entry);
                const row = entry;
                entry.bridge = effect(() => {
                    if (this.refreshOwnedMarkdownPresentation(row.context, row.content(), row.classifier())) {
                        this.changeDetector?.markForCheck();
                    }
                }, { injector: this.injector, manualCleanup: true });
            }
            else {
                if (entry.generation !== generation || entry.classifiedContent !== content) {
                    const classifier = this.classifyMessage(content, message);
                    entry.classifier.set(classifier);
                    entry.content.set(content);
                    entry.generation = generation;
                    entry.classifiedContent = content;
                }
                const prior = entry.delivery();
                if (prior.delivery.generation !== generation || prior.delivery.phase !== message.delivery.phase) {
                    entry.delivery.set({ id: message.id, delivery: { ...message.delivery } });
                }
                this.refreshOwnedMarkdownPresentation(entry.context, content, entry.classifier());
            }
        }
        for (const key of this.ownedMarkdownBodies.keys()) {
            if (!liveIds.has(key))
                this.removeOwnedMarkdownBody(key);
        }
    }
    private ownedMarkdownPresentation(content: string, classifier: ContentClassifier): OwnedMarkdownPresentation {
        return {
            content, type: classifier.type(), spec: classifier.spec(),
            surfaces: classifier.a2uiSurfaces(), surfaceStates: classifier.a2uiSurfaceStates(),
        };
    }
    private refreshOwnedMarkdownPresentation(context: OwnedMarkdownRowContext, content: string, classifier: ContentClassifier): boolean {
        const next = this.ownedMarkdownPresentation(content, classifier);
        const prior = context.presentation;
        if (prior.content === next.content && prior.type === next.type && prior.spec === next.spec
            && prior.surfaces === next.surfaces && prior.surfaceStates === next.surfaceStates)
            return false;
        Object.assign(prior, next);
        return true;
    }
    private removeOwnedMarkdownBody(id: string): void {
        this.ownedMarkdownBodies.get(id)?.bridge?.destroy();
        this.ownedMarkdownBodies.delete(id);
    }
    protected ownedMarkdownBodyFor(id: string): OwnedMarkdownContext {
        return this.ownedMarkdownBodies.get(id)!.context;
    }
    protected ownedMarkdownPresentationFor(id: string): OwnedMarkdownPresentation {
        const row = this.ownedMarkdownBodies.get(id);
        if (!row)
            throw new Error('Owned markdown presentation is unavailable');
        return row.context.presentation;
    }
    classifyMessage(content: string, message: Pick<Message, 'id' | 'delivery'>): ContentClassifier {
        const generation = message.delivery.generation;
        let entry = this.classifiers.get(message.id);
        if (!entry || entry.generation !== generation) {
            entry?.classifier.dispose();
            entry = { generation, classifier: createContentClassifier() };
            this.classifiers.set(message.id, entry);
        }
        if (entry.content !== content) {
            entry.classifier.update(content);
            entry.content = content;
        }
        return entry.classifier;
    }
    protected markdownDocumentFor(content: string, message: Pick<Message, 'id' | 'delivery'>): StreamingMarkdownDocument {
        const prior = this.markdownDocuments.get(message.id);
        const delivery = message.delivery;
        if (prior?.generation === delivery.generation &&
            prior.phase === delivery.phase &&
            prior.content === content) {
            return prior;
        }
        const document = markdownDocument(content, delivery);
        this.markdownDocuments.set(message.id, document);
        return document;
    }
    clearClassifiers(): void {
        for (const key of this.ownedMarkdownBodies.keys())
            this.removeOwnedMarkdownBody(key);
        for (const [, entry] of this.classifiers) {
            entry.classifier.dispose();
        }
        this.classifiers.clear();
        this.markdownDocuments.clear();
        this.activityContexts.clear();
    }
    onSpecEvent(event: RenderEvent, messageIndex: number): void {
        this.renderEvent.emit({ messageIndex, event });
    }
    protected onClientToolEvent(event: RenderEvent): void {
        const coord = this.coordinator();
        if (!coord)
            return;
        let agentRef: ReturnType<typeof this.agent>;
        try {
            agentRef = this.agent();
        }
        catch {
            return;
        }
        coord.handleRenderEvent(agentRef, event);
    }
    onA2uiAction(message: A2uiActionMessage): void {
        if (this.agent().isInputBlocked?.())
            return;
        void this.agent().submit({ message: JSON.stringify(message) });
    }
    onA2uiEvent(event: RenderEvent, messageIndex: number, surfaceId: string): void {
        this.renderEvent.emit({ messageIndex, surfaceId, event });
    }
    onRegenerate(messageIndex: number): void {
        this.upwardWheel = undefined;
        this.pinned.set(true);
        void this.agent().regenerate(messageIndex);
        this.regenerate.emit();
    }
    onRate(message: unknown, value: 'up' | 'down'): void {
        const idx = this.agent().messages().indexOf(message as never);
        this.rate.emit({ messageIndex: idx, rating: value });
    }
    onCopy(message: unknown, content: string): void {
        const idx = this.agent().messages().indexOf(message as never);
        this.messageCopy.emit({ messageIndex: idx, content });
    }
}

