@Directive({
    selector: '[chatConnectedOverlay]',
    standalone: true,
})
export class ChatConnectedOverlayDirective {
    readonly origin = input.required<ChatOverlayOriginDirective>({ alias: 'chatOverlayOrigin' });
    readonly open = input<boolean>(false, { alias: 'chatOverlayOpen' });
    readonly positions = input<ConnectedPosition[]>([], { alias: 'chatOverlayPositions' });
    readonly panelClass = input<string | string[]>('', { alias: 'chatOverlayPanelClass' });
    readonly attached = output<HTMLElement>({ alias: 'chatOverlayAttached' });
    readonly outsideClick = output<MouseEvent>({ alias: 'chatOverlayOutsideClick' });
    readonly detached = output<void>({ alias: 'chatOverlayDetach' });
    private readonly templateRef = inject(TemplateRef<unknown>);
    private readonly viewContainerRef = inject(ViewContainerRef);
    private readonly document = inject(DOCUMENT);
    private pane: HTMLElement | null = null;
    private viewRef: EmbeddedViewRef<unknown> | null = null;
    private resizeObs: ResizeObserver | null = null;
    private rafId = 0;
    private previouslyFocused: HTMLElement | null = null;
    private readonly onScrollOrResize = () => this.scheduleReposition();
    private readonly onDocMouseDown = (e: MouseEvent) => {
        if (!this.pane)
            return;
        const path = e.composedPath();
        if (path.includes(this.pane) || path.includes(this.origin().elementRef.nativeElement))
            return;
        this.outsideClick.emit(e);
    };
    private readonly onKeydown = (e: KeyboardEvent) => {
        if (e.key !== 'Tab' || !this.pane)
            return;
        const active = this.document.activeElement;
        if (this.pane.contains(active) || active === this.origin().elementRef.nativeElement) {
            this.detached.emit();
        }
    };
    constructor() {
        effect(() => {
            if (this.open())
                this.attach();
            else
                this.dispose();
        });
        inject(DestroyRef).onDestroy(() => this.dispose());
    }
    private attach(): void {
        if (this.pane)
            return;
        const win = this.document.defaultView;
        if (!win)
            return;
        this.previouslyFocused = this.document.activeElement as HTMLElement | null;
        const pane = this.document.createElement('div');
        pane.className = 'chat-overlay-pane';
        for (const c of this.normalizePanelClass())
            pane.classList.add(c);
        getOverlayContainer(this.document).appendChild(pane);
        this.viewRef = this.viewContainerRef.createEmbeddedView(this.templateRef);
        this.viewRef.detectChanges();
        for (const node of this.viewRef.rootNodes)
            pane.appendChild(node as Node);
        this.pane = pane;
        this.reposition();
        win.addEventListener('scroll', this.onScrollOrResize, { capture: true, passive: true });
        win.addEventListener('resize', this.onScrollOrResize, { passive: true });
        this.document.addEventListener('mousedown', this.onDocMouseDown, true);
        this.document.addEventListener('keydown', this.onKeydown, true);
        if (typeof win.ResizeObserver === 'function') {
            this.resizeObs = new win.ResizeObserver(() => this.scheduleReposition());
            this.resizeObs.observe(this.origin().elementRef.nativeElement);
            this.resizeObs.observe(pane);
        }
        this.attached.emit(pane);
    }
    private scheduleReposition(): void {
        const win = this.document.defaultView;
        if (!win || !this.pane)
            return;
        if (this.rafId)
            win.cancelAnimationFrame(this.rafId);
        this.rafId = win.requestAnimationFrame(() => this.reposition());
    }
    private reposition(): void {
        const win = this.document.defaultView;
        if (!win || !this.pane)
            return;
        const r = this.pane.getBoundingClientRect();
        const result = computeConnectedPosition({
            originRect: this.origin().elementRef.nativeElement.getBoundingClientRect(),
            overlaySize: { width: r.width, height: r.height },
            viewport: narrowViewport(win, VIEWPORT_MARGIN),
            positions: this.positions(),
        });
        this.pane.style.top = `${Math.round(result.top)}px`;
        this.pane.style.left = `${Math.round(result.left)}px`;
    }
    private dispose(): void {
        const win = this.document.defaultView;
        if (this.rafId && win)
            win.cancelAnimationFrame(this.rafId);
        this.rafId = 0;
        if (win) {
            win.removeEventListener('scroll', this.onScrollOrResize, { capture: true } as EventListenerOptions);
            win.removeEventListener('resize', this.onScrollOrResize);
        }
        this.document.removeEventListener('mousedown', this.onDocMouseDown, true);
        this.document.removeEventListener('keydown', this.onKeydown, true);
        this.resizeObs?.disconnect();
        this.resizeObs = null;
        const focusWasInPane = !!this.pane && this.pane.contains(this.document.activeElement);
        this.viewRef?.destroy();
        this.viewRef = null;
        this.pane?.remove();
        this.pane = null;
        if (focusWasInPane && this.previouslyFocused)
            this.previouslyFocused.focus();
        this.previouslyFocused = null;
    }
    private normalizePanelClass(): string[] {
        const pc = this.panelClass();
        return Array.isArray(pc) ? pc : pc ? [pc] : [];
    }
}

@Component({
    selector: 'chat-error',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [CHAT_HOST_TOKENS, CHAT_ERROR_STYLES],
    template: `
    @if (agent().error(); as err) {
      <div class="chat-error" role="alert">
        <svg class="chat-error__icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/>
        </svg>
        <span class="chat-error__msg">{{ err.message }}</span>
        <!-- The action comes before the detail in source order so it shares the
             first row with the message, the way Retry always has. The detail
             claims a full row of its own, so a button after it would be pushed
             to a third row and the two actions would sit differently. -->
        @if (err.recovery === 'check') {
          @if (agent().checkStatus) {
            <button type="button" class="chat-error__check" (click)="agent().checkStatus!()">Check status</button>
          }
        } @else if (err.retryable && !retryHidden()) {
          <button type="button" class="chat-error__retry" (click)="agent().retry()">Retry</button>
        }
        @if (err.detail) {
          <span class="chat-error__detail">{{ err.detail }}</span>
        }
      </div>
    }
  `,
})
export class ChatErrorComponent {
    readonly agent = input.required<Agent>();
    readonly retryHidden = input(false);
}

@Component({
    selector: 'chat-generative-ui',
    standalone: true,
    imports: [RenderSpecComponent],
    changeDetection: ChangeDetectionStrategy.OnPush,
    styles: [CHAT_HOST_TOKENS, CHAT_GENERATIVE_UI_STYLES],
    viewProviders: [ɵprovideRenderDevtools()],
    template: `
    @if (normalizedSpec()) {
      <render-spec
        [spec]="normalizedSpec()"
        [registry]="registry()"
        [store]="store()"
        [handlers]="handlers()"
        [loading]="loading()"
        (events)="events.emit($event)"
      />
    }
  `,
})
export class ChatGenerativeUiComponent {
    readonly spec = input<Spec | null>(null);
    readonly registry = input<AngularRegistry | undefined>(undefined);
    readonly store = input<StateStore | undefined>(undefined);
    readonly handlers = input<Record<string, (params: Record<string, unknown>) => unknown | Promise<unknown>> | undefined>(undefined);
    readonly loading = input<boolean>(false);
    readonly events = output<RenderEvent>();
    protected readonly normalizedSpec = computed(() => {
        const s = this.spec();
        return s ? normalizeJsonRenderSpec(s) : null;
    });
    private readonly seeded = new Map<string, unknown>();
    constructor() {
        effect(() => {
            const s = this.spec();
            const store = this.store();
            const state = s?.state as Record<string, unknown> | undefined;
            if (!state || !store)
                return;
            untracked(() => {
                for (const [key, value] of Object.entries(state)) {
                    const path = key.startsWith('/') ? key : `/${key}`;
                    const current = store.get(path);
                    const untouched = current === undefined ||
                        (this.seeded.has(path) && current === this.seeded.get(path));
                    if (untouched) {
                        if (current !== value)
                            store.set(path, value);
                        this.seeded.set(path, value);
                    }
                }
            });
        });
    }
}

