      #origin="chatOverlayOrigin"
      [class.is-open]="open()"
      [disabled]="disabled()"
      [attr.aria-haspopup]="'listbox'"
      [attr.aria-expanded]="open()"
      [attr.aria-controls]="open() ? menuId : null"
      (click)="toggle()"
      (keydown)="onTriggerKeydown($event)"
    >
