export async function validateArgs(schema: StandardSchemaV1, args: unknown): Promise<{
    ok: true;
    value: unknown;
} | {
    ok: false;
    error: string;
}> {
    const res = await schema['~standard'].validate(args);
    if (res.issues) {
        return { ok: false, error: res.issues.map((i) => i.message).join('; ') };
    }
    return { ok: true, value: (res as {
            value: unknown;
        }).value };
}

