export function citationSourceVisual(c: Citation): CitationSourceVisual {
    const iconUrl = c.iconUrl?.trim();
    if (iconUrl) {
        return { kind: 'image', iconUrl };
    }
    const meta = citationTypeMeta(c);
    if (meta.icon !== 'web') {
        return {
            kind: 'type-icon',
            icon: meta.icon,
            tone: meta.tone,
            label: meta.label,
        };
    }
    return {
        kind: 'monogram',
        monogram: deriveMonogram(c),
        color: monogramColor(c),
    };
}

export function citationTypeLabel(c: Citation): string | null {
    return citationTypeMeta(c).label;
}

export function citationTypeMeta(c: Citation): CitationTypeMeta {
    const type = deriveSourceType(c);
    const canonicalType = type.toLowerCase();
    if (isKnownType(canonicalType)) {
        return {
            type: canonicalType,
            label: KNOWN_TYPE_LABELS[canonicalType],
            icon: canonicalType,
            tone: canonicalType,
            isKnown: true,
        };
    }
    return {
        type,
        label: type === 'unknown' ? null : readableSourceTypeLabel(type),
        icon: 'generic',
        tone: 'generic',
        isKnown: false,
    };
}

export function createMessageContent<TTools extends {
    [K in keyof TTools]: ToolContract;
} = Record<string, ToolContract>>(options: MessageContentOptions = {}): MessageContent<TTools> {
    const factory = options.markdownFactory ?? createMarkdown;
    const owners = new Map<string, Markdown>();
    const reasoningOwners = new Map<string, Markdown>();
    const projectMarkdown = (collection: Map<string, Markdown>, id: string, document: MarkdownDocument): MarkdownSnapshot => {
        let owner = collection.get(id);
        if (!owner) {
            owner = factory(document, { violationPolicy: 'rebuild' });
            collection.set(id, owner);
        }
        else {
            const accepted = owner.getSnapshot().document;
            if (accepted.generation !== document.generation ||
                accepted.phase !== document.phase ||
                accepted.content !== document.content)
                owner.update(document);
        }
        return owner.getSnapshot();
    };
    let rows: readonly MessageRow<TTools>[] = Object.freeze([]);
    let messages: readonly Message[] | undefined;
    let toolCalls: readonly ToolCall<TTools>[] | undefined;
    let disposed = false;
    return {
        project(snapshot) {
            const next = snapshot as {
                readonly messages: readonly Message[];
                readonly toolCalls: readonly ToolCall<TTools>[];
            };
            const projectedCalls = next.toolCalls;
            if (disposed ||
                (next.messages === messages && next.toolCalls === toolCalls))
                return rows;
            const present = new Set(next.messages.map((message) => message.id));
            for (const collection of [owners, reasoningOwners]) {
                for (const [id, owner] of collection) {
                    if (present.has(id))
                        continue;
                    owner.dispose();
                    collection.delete(id);
                }
            }
            const previous = new Map(rows.map((row) => [row.id, row]));
            const projected = next.messages.map((message): MessageRow<TTools> => {
                const document = {
                    generation: message.delivery.generation,
                    phase: message.delivery.phase,
                    content: message.content,
                };
                const markdown = projectMarkdown(owners, message.id, document);
                let reasoning: MarkdownSnapshot | undefined;
                if (message.reasoning !== undefined && message.reasoning.length > 0) {
                    reasoning = projectMarkdown(reasoningOwners, message.id, {
                        generation: `${message.delivery.generation}:reasoning`,
                        phase: message.delivery.phase,
                        content: message.reasoning,
                    });
                }
                else {
                    reasoningOwners.get(message.id)?.dispose();
                    reasoningOwners.delete(message.id);
                }
                const calls = projectedCalls.filter((call) => message.toolCallIds?.includes(call.id) ||
                    message.toolCallId === call.id);
                const old = previous.get(message.id);
                if (old?.message === message &&
                    old.markdown === markdown &&
                    old.reasoning === reasoning &&
                    old.toolCalls.length === calls.length &&
                    calls.every((call, index) => call === old.toolCalls[index]))
                    return old;
                return Object.freeze({
                    id: message.id,
                    role: message.role,
                    message,
                    markdown,
                    ...(reasoning === undefined ? {} : { reasoning }),
                    toolCalls: Object.freeze(calls),
                });
            });
            if (projected.length !== rows.length ||
                projected.some((row, index) => row !== rows[index]))
                rows = Object.freeze(projected);
            messages = next.messages;
            toolCalls = next.toolCalls;
            return rows;
        },
        dispose() {
            if (disposed)
                return;
            disposed = true;
            for (const collection of [owners, reasoningOwners]) {
                for (const owner of collection.values())
                    owner.dispose();
                collection.clear();
            }
        },
    };
}

export function deriveDomain(url?: string): string | null {
    if (!url)
        return null;
    try {
        return new URL(url).hostname.replace(/^www\./, '');
    }
    catch {
        return null;
    }
}

export function deriveMonogram(c: Citation): string {
    const seed = deriveDomain(c.url) ?? c.title ?? '';
    const ch = seed.trim().charAt(0);
    return ch ? ch.toUpperCase() : '?';
}

export function deriveSourceType(c: Citation): string {
    const explicit = c.sourceType?.trim();
    if (explicit)
        return explicit;
    return c.url ? 'web' : 'unknown';
}

export function formatPublished(value?: string | number | Date): string | null {
    if (value == null)
        return null;
    const d = value instanceof Date ? value : new Date(value);
    if (Number.isNaN(d.getTime()))
        return null;
    return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short' });
}

export function monogramColor(c: Citation): string {
    const seed = deriveDomain(c.url) ?? c.title ?? '?';
    return `hsl(${monogramHue(seed)} 60% 45%)`;
}

export function monogramHue(seed: string): number {
    let h = 0;
    for (let i = 0; i < seed.length; i++) {
        h = (h * 31 + seed.charCodeAt(i)) % 360;
    }
    return h;
}

