}

export function mockLangGraphAgent(initial: MockAgentOptions & {
    langGraphMessages?: BaseMessage[];
    hasValue?: boolean;
    isThreadLoading?: boolean;
} = {}): MockLangGraphAgent {
    const base = mockAgent({
        ...initial,
        withInterrupt: true,
        withSubagents: true,
        history: initial.history ?? [],
    });
    const langGraphMessages$ = signal<BaseMessage[]>(initial.langGraphMessages ?? []);
    const hasValue$ = signal<boolean>(initial.hasValue ?? false);
    const value$ = signal<any>(null);
    const langGraphInterrupts$ = signal<Interrupt<any>[]>([]);
    const langGraphToolCalls$ = signal<ToolCallWithResult[]>([]);
    const toolProgress$ = signal<ToolProgress[]>([]);
    const queue$ = signal<AgentQueue>({
        entries: [],
        size: 0,
        cancel: async () => false,
        clear: async () => undefined,
    });
    const branch$ = signal<string>('');
    const langGraphHistory$ = signal<ThreadState<any>[]>([]);
    const experimentalBranchTree$ = signal<AgentBranchTree<any>>({ type: 'sequence', items: [] });
    const isThreadLoading$ = signal<boolean>(initial.isThreadLoading ?? false);
    const activeSubagents$ = signal<SubagentStreamRef[]>([]);
    const customEvents$ = signal<CustomStreamEvent[]>([]);
    const state$ = computed<Record<string, unknown>>(() => {
        const v = value$();
        return v && typeof v === 'object' ? (v as Record<string, unknown>) : {};
    });
    const mock: MockLangGraphAgent = {
        ...base,
        state: state$ as never,
        langGraphMessages: langGraphMessages$,
        langGraphInterrupts: langGraphInterrupts$,
        langGraphToolCalls: langGraphToolCalls$,
        langGraphHistory: langGraphHistory$,
        experimentalBranchTree: experimentalBranchTree$,
        value: value$,
        hasValue: hasValue$,
        reload: () => { },
        toolProgress: toolProgress$,
        queue: queue$,
        activeSubagents: activeSubagents$,
        getSubagent: (toolCallId: string) => activeSubagents$().find(subagent => subagent.toolCallId === toolCallId),
        getSubagentsByType: (type: string) => activeSubagents$().filter(subagent => subagent.name === type),
        getSubagentsByMessage: (msg: CoreAIMessage) => {
            const toolCalls = (msg as unknown as Record<string, unknown>)['tool_calls'];
            if (!Array.isArray(toolCalls))
                return [];
            const ids = toolCalls
                .map(toolCall => {
                if (toolCall == null || typeof toolCall !== 'object' || Array.isArray(toolCall))
                    return undefined;
                const id = (toolCall as Record<string, unknown>)['id'];
                return typeof id === 'string' ? id : undefined;
            })
                .filter((id): id is string => id != null);
            return activeSubagents$().filter(subagent => ids.includes(subagent.toolCallId));
        },
        customEvents: customEvents$,
        branch: branch$,
        setBranch: (_branch: string) => { },
        isThreadLoading: isThreadLoading$,
        switchThread: (_threadId: string | null) => { },
        joinStream: (_runId: string, _lastEventId?: string) => Promise.resolve(),
        getMessagesMetadata: (_msg: BaseMessage, _idx?: number): MessageMetadata<Record<string, unknown>> | undefined => undefined,
        getToolCalls: (_msg: CoreAIMessage): ToolCallWithResult[] => [],
        lifecycle: {
            streamStartedAt: signal<number | null>(null),
            streamErrorAt: signal<{
                at: number;
                kind: AgentErrorKind | string;
            } | null>(null),
            interruptReceivedAt: signal<number | null>(null),
            interruptResolvedAt: signal<number | null>(null),
            threadCreatedAt: signal<number | null>(null),
            threadPersistedAt: signal<number | null>(null),
            toolCallStartedAt: signal<number | null>(null),
            toolCallCompletedAt: signal<number | null>(null),
        },
    } as MockLangGraphAgent;
    return mock;
}

export function provideAgent<T = Record<string, unknown>>(refOrConfig: AgentRef<T> | AgentConfig<T> | (() => AgentConfig<T>), maybeConfig?: AgentConfig<T> | (() => AgentConfig<T>)): Provider[] {
    const ref = isAgentRef<T>(refOrConfig) ? refOrConfig : undefined;
    const configOrFactory = (ref ? maybeConfig : refOrConfig) as AgentConfig<T> | (() => AgentConfig<T>);
    const resolveConfig = (): AgentConfig<T> => typeof configOrFactory === 'function' ? (configOrFactory as () => AgentConfig<T>)() : configOrFactory;
    if (!ref) {
        return [
            { provide: AGENT_CONFIG, useFactory: resolveConfig },
            { provide: AGENT, useFactory: agentFactory<T> },
            { provide: AGENT_LIFECYCLE, useFactory: () => inject(AGENT).lifecycle },
        ];
    }
    const refConfig = new InjectionToken<AgentConfig<T>>(`AGENT_CONFIG(${ref.token.toString()})`);
    const thisRefName = refDebugName(ref as AgentRef<unknown>);
    return [
        { provide: refConfig, useFactory: resolveConfig },
        { provide: ref.token, useFactory: () => createAgentFromConfig(inject(refConfig)) },
        { provide: AGENT_CONFIG, useExisting: refConfig },
        { provide: AGENT_REF_NAMES, useValue: thisRefName, multi: true },
        {
            provide: AGENT,
            useFactory: () => {
                if (isDevMode()) {
                    const names = inject(AGENT_REF_NAMES, { optional: true }) ?? [];
                    const others = names.filter((n) => n !== thisRefName);
                    if (others.length > 0) {
                        console.warn(`[@threadplane/langgraph] provideAgent(): ${names.length} agent refs ` +
                            `(${names.join(', ')}) are provided at the same injector level. ` +
                            `The ref-less injectAgent() resolves a single shared token, so it now ` +
                            `returns the last one provided (${thisRefName}). ` +
                            `Inject by ref — injectAgent(${others[0]}) / injectAgent(${thisRefName}) — ` +
                            `to reach each agent unambiguously.`);
                    }
                }
                return inject(ref.token) as LangGraphAgent<T>;
            },
        },
        {
            provide: AGENT_LIFECYCLE,
            useFactory: () => (inject(ref.token) as LangGraphAgent<T>).lifecycle,
        },
    ];
}

export function provideFakeAgent(config: FakeAgentConfig = {}): Provider[] {
    return provideAgent({
