export function refreshOnRunEnd(agent: LangGraphAgent, fn: () => void | Promise<void>): void {
    let lastStatus = agent.status();
    effect(() => {
        const status = agent.status();
        if (lastStatus === 'running' && status !== 'running') {
            void fn();
        }
        lastStatus = status;
    });
}

export function refreshOnTransition<T>(watch: Signal<T>, isActive: (v: T) => boolean, fn: () => void | Promise<void>): void {
    let lastActive = isActive(watch());
    effect(() => {
        const active = isActive(watch());
        if (lastActive && !active)
            void fn();
        lastActive = active;
    });
}

export function toAbsoluteApiUrl(apiUrl: string): string {
    if (apiUrl.startsWith('http://') || apiUrl.startsWith('https://'))
        return apiUrl;
    const browser = globalThis as typeof globalThis & {
        window?: {
            location: {
                origin: string;
            };
        };
    };
    return browser.window !== undefined ? `${browser.window.location.origin}${apiUrl}` : apiUrl;
}

