export function createInMemoryClientToolExecutionStore(): ClientToolExecutionStore {
    const records = new Map<string, RecordState>();
    return {
        async acquire(key, invocation) {
            const threadId = key.threadId;
            const toolCallId = key.toolCallId;
            const identity = JSON.stringify([threadId, toolCallId]);
            const existing = records.get(identity);
            if (existing) {
                if (existing.invocation !== invocation)
                    return { status: 'conflict' };
                return existing.status === 'done' && existing.result !== null
                    ? { status: 'complete', result: existing.result }
                    : { status: 'unavailable' };
            }
            const token = crypto.randomUUID();
            records.set(identity, {
                invocation,
                token,
                status: 'executing',
                result: null,
            });
            return { status: 'acquired', token };
        },
        async settle(key, settlement) {
            const threadId = key.threadId;
            const toolCallId = key.toolCallId;
            const invocation = settlement.invocation;
            const token = settlement.token;
            const result = settlement.result;
            const identity = JSON.stringify([threadId, toolCallId]);
            const existing = records.get(identity);
            if (!existing ||
                existing.invocation !== invocation ||
                existing.token !== token)
                return 'rejected';
            if (existing.status === 'done')
                return existing.result !== null && existing.result === result
                    ? 'accepted'
                    : 'rejected';
            records.set(identity, { invocation, token, status: 'done', result });
            return 'accepted';
        },
    };
}

export function createPostgresClientToolExecutionStore(sql: PostgresTaggedSql, opts: PostgresClientToolExecutionStoreOptions = {}): ClientToolExecutionStore {
    const tenantId = opts.tenantId ?? '';
    return {
        async acquire(key, invocation) {
            const threadId = key.threadId;
            const toolCallId = key.toolCallId;
            const token = crypto.randomUUID();
            const inserted = await sql `
        INSERT INTO threadplane_client_tool_executions
          (tenant_id, thread_id, tool_call_id, status, invocation, owner_token)
        VALUES (${tenantId}, ${threadId}, ${toolCallId}, 'executing', ${invocation}, ${token})
        ON CONFLICT (tenant_id, thread_id, tool_call_id) DO NOTHING
        RETURNING owner_token
      `;
            if (inserted.length > 0)
                return inserted.length === 1 && inserted[0]?.['owner_token'] === token
                    ? { status: 'acquired', token }
                    : { status: 'unavailable' };
            const existing = await sql `
        SELECT status, invocation, owner_token, encoded_result
        FROM threadplane_client_tool_executions
        WHERE tenant_id COLLATE "C" = ${tenantId} COLLATE "C"
          AND thread_id COLLATE "C" = ${threadId} COLLATE "C"
          AND tool_call_id COLLATE "C" = ${toolCallId} COLLATE "C"
        LIMIT 1
      `;
            return observe(existing[0], invocation);
        },
        async settle(key, settlement) {
            const threadId = key.threadId;
            const toolCallId = key.toolCallId;
            const invocation = settlement.invocation;
            const token = settlement.token;
            const result = settlement.result;
            if (typeof invocation !== 'string' ||
                typeof token !== 'string' ||
                !ownerPattern.test(token) ||
                (result !== null && typeof result !== 'string'))
                return 'rejected';
            const updated = await sql `
        UPDATE threadplane_client_tool_executions
        SET status = 'done', encoded_result = ${result},
          updated_at = CASE WHEN status = 'executing' THEN now() ELSE updated_at END
        WHERE tenant_id COLLATE "C" = ${tenantId} COLLATE "C"
          AND thread_id COLLATE "C" = ${threadId} COLLATE "C"
          AND tool_call_id COLLATE "C" = ${toolCallId} COLLATE "C"
          AND owner_token COLLATE "C" = ${token} COLLATE "C"
          AND invocation COLLATE "C" = ${invocation} COLLATE "C"
          AND ((status = 'executing' AND encoded_result IS NULL)
            OR (status = 'done' AND encoded_result IS NOT NULL
              AND encoded_result COLLATE "C" = ${result} COLLATE "C"))
        RETURNING owner_token
      `;
            return updated.length === 1 && updated[0]?.['owner_token'] === token
                ? 'accepted'
                : 'rejected';
        },
    };
}

export function hasClientToolCall(state: ClientToolsState): boolean {
    const names = clientToolNames(state);
    return toolCalls(lastMessage(state)).some((c) => {
        const n = callName(c);
        return n !== undefined && names.has(n);
    });
}

export function hasServerToolCall(state: ClientToolsState, serverToolNames: Iterable<string>): boolean {
    const server = new Set(serverToolNames);
    const client = clientToolNames(state);
    return toolCalls(lastMessage(state)).some((c) => {
        const n = callName(c);
        return n !== undefined && (server.has(n) || !client.has(n));
    });
}

export function lastMessage(state: ClientToolsState): BaseMessage | undefined {
    const msgs = state.messages ?? [];
    return msgs.length ? msgs[msgs.length - 1] : undefined;
}

export function routeAfterAgent(state: ClientToolsState, serverToolNames: Iterable<string>, opts?: {
    toolsNode?: string;
    end?: string;
}): string {
    const toolsNode = opts?.toolsNode ?? 'server_tools';
    const end = opts?.end ?? '__end__';
    return hasServerToolCall(state, serverToolNames) ? toolsNode : end;
}

