export function Chat({ session, content, renderMessage, className, groupRelatedTools, toolLabel, toolOutcome, renderToolResult, onToolRetry, onRetry, inputLeading, inputTrailing, inputFooter, ...input }: ChatProps) {
    const snapshot = useAgent(session);
    const stop = useCallback(() => {
        session.stop().catch(ignore);
    }, [session]);
    const rows = useMessageContent(snapshot, session, content);
    return (<div className={['tp-chat', className].filter(Boolean).join(' ')}>
      <MessageList rows={rows} renderMessage={renderMessage} groupRelatedTools={groupRelatedTools} toolLabel={toolLabel} toolOutcome={toolOutcome} renderToolResult={renderToolResult} onToolRetry={onToolRetry} plan={snapshot.plan} onStop={snapshot.status === 'running' ? stop : undefined} renderScrollControl={(controls) => controls.pinned ? null : (<ScrollBubble mode={snapshot.status === 'running' ? 'streaming' : 'idle'} onClick={() => {
                controls.scrollToLatest();
                controls.focus();
            }}/>)}/>
      <TypingIndicator active={isTyping(snapshot)}/>
      <ChatError error={snapshot.error} className="tp-chat__error" onRetry={onRetry &&
            (() => {
                if (session.getSnapshot().error === snapshot.error)
                    onRetry();
            })} onCheckStatus={session.checkStatus &&
            (() => {
                const checkStatus = session.checkStatus;
                if (checkStatus && session.getSnapshot().error === snapshot.error) {
                    checkStatus.call(session).catch(ignore);
                }
            })}/>
      <ChatInput key={sessionKey(session)} {...input} leading={inputLeading} trailing={inputTrailing} footer={inputFooter} busy={snapshot.status === 'running'} onSubmit={(text) => {
            session.submit(text.trim()).catch(ignore);
        }} onStop={() => {
            session.stop().catch(ignore);
        }}/>
    </div>);
}

export function ChatError({ error, onRetry, onCheckStatus, disabled, className, }: ChatErrorProps) {
    if (error == null)
        return null;
    const retry = error.retryable &&
        (error.recovery === 'retry' || error.recovery === undefined);
    const action = error.recovery === 'check' ? onCheckStatus : retry ? onRetry : undefined;
    return (<div role="alert" className={['tp-chat-error', className].filter(Boolean).join(' ')}>
      <p className="tp-chat-error__message">{error.message}</p>
      {action && (<button type="button" disabled={disabled} onClick={() => action()}>
          {error.recovery === 'check' ? 'Check status' : 'Retry response'}
        </button>)}
      {error.detail && <p className="tp-chat-error__detail">{error.detail}</p>}
    </div>);
}

