export function Citations({ citations, snapshot, label = 'Sources', className, preview, renderCard, collapsible, }: CitationsProps) {
    if (new Set(citations.map((citation) => citation.id)).size !== citations.length)
        throw new TypeError('Duplicate citation IDs in Sources.');
    if (snapshot !== undefined) {
        const merged = new Map(citations.map((citation) => [citation.id, citation]));
        for (const definition of snapshot.root?.citations.values() ?? []) {
            if (!merged.has(definition.id))
                merged.set(definition.id, definitionToCitation(definition));
        }
        citations = [...merged.values()].sort((a, b) => a.index - b.index);
    }
    if (!citations.length)
        return null;
    if (collapsible === true)
        return (<Disclosure citations={citations} label={label} className={className} preview={preview} renderCard={renderCard}/>);
    return (<section aria-label={label} className={['tp-citations', className].filter(Boolean).join(' ')}>
      <h4 className="tp-citations__heading">{label}</h4>
      <SourceList citations={citations} preview={preview} renderCard={renderCard}/>
    </section>);
}

