export function MessageList<TRow extends MessageRow = MessageRow>({ rows, renderMessage, label = 'Conversation', className, groupRelatedTools = true, toolLabel, toolOutcome, renderToolResult, onToolRetry, plan, onStop, children, renderScrollControl, }: MessageListProps<TRow>) {
    const staleRetries = useMemo(() => (onToolRetry ? staleRetriesByRow(rows) : undefined), [onToolRetry, rows]);
    const retrying = useMemo(() => (toolOutcome ? retryingByRow(rows) : undefined), [toolOutcome, rows]);
    const container = useRef<HTMLDivElement>(null);
    const content = useRef<HTMLDivElement>(null);
    const pinned = useRef(true);
    const [isPinned, setIsPinned] = useState(true);
    const active = useRef(false);
    const lastScrollTop = useRef(0);
    const setPinned = useCallback((value: boolean) => {
        if (pinned.current !== value) {
            pinned.current = value;
            setIsPinned(value);
        }
    }, []);
    const scrollToLatest = useCallback(() => {
        const el = container.current;
        if (!active.current || !el)
            return;
        setPinned(true);
        el.scrollTop = el.scrollHeight;
        lastScrollTop.current = el.scrollTop;
    }, [setPinned]);
    const focus = useCallback(() => {
        if (active.current)
            container.current?.focus({ preventScroll: true });
    }, []);
    const controls = useMemo<MessageListScrollControls>(() => ({ pinned: isPinned, scrollToLatest, focus }), [isPinned, scrollToLatest, focus]);
    useIsomorphicLayoutEffect(() => {
        active.current = true;
        return () => {
            active.current = false;
        };
    }, []);
    useEffect(() => {
        const el = container.current;
        if (!el)
            return;
        let listening = true;
        const onScroll = () => {
            if (!listening || !active.current)
                return;
            const max = Math.max(0, el.scrollHeight - el.clientHeight);
            if (el.scrollTop < Math.min(lastScrollTop.current, max) - 1)
                setPinned(false);
            else if (max - el.scrollTop <= PIN_THRESHOLD)
                setPinned(true);
            lastScrollTop.current = el.scrollTop;
        };
        el.addEventListener('scroll', onScroll, { passive: true });
        return () => {
            listening = false;
            el.removeEventListener('scroll', onScroll);
        };
    }, [setPinned]);
    useIsomorphicLayoutEffect(() => {
        const el = container.current;
        const body = content.current;
        if (!el || !body || typeof ResizeObserver === 'undefined')
            return;
        let active = true;
        const observer = new ResizeObserver(() => {
            if (active && pinned.current) {
                el.scrollTop = el.scrollHeight;
                lastScrollTop.current = el.scrollTop;
            }
        });
        observer.observe(body);
        observer.observe(el);
        return () => {
            active = false;
            observer.disconnect();
        };
    }, []);
    useIsomorphicLayoutEffect(() => {
        const el = container.current;
        if (el && pinned.current) {
            el.scrollTop = el.scrollHeight;
            lastScrollTop.current = el.scrollTop;
        }
    }, [rows, children]);
    return (<>
      <div ref={container} role="region" tabIndex={0} aria-label={label} className={['tp-chat-list', className].filter(Boolean).join(' ')}>
        <div ref={content}>
          {rows.map((row, index) => (<Row key={row.id} row={row} current={index === rows.length - 1} prevRole={rows[index - 1]?.role} renderMessage={renderMessage} groupRelatedTools={groupRelatedTools} toolLabel={toolLabel} toolOutcome={toolOutcome} renderToolResult={renderToolResult} onToolRetry={onToolRetry} staleRetries={staleRetries?.[index]} retrying={retrying?.[index]} plan={index === rows.length - 1 ? plan : undefined} onStop={index === rows.length - 1 ? onStop : undefined}/>))}
          {children}
        </div>
      </div>
      {renderScrollControl?.(controls)}
    </>);
}

