export function Reasoning({ snapshot, durationMs, label, defaultExpanded = false, className, }: ReasoningProps) {
    const { generation, phase, content } = snapshot.document;
    const streaming = phase === 'streaming';
    const id = useId();
    const [choice, setChoice] = useState({
        generation,
        phase,
        expanded: null as boolean | null,
    });
    let current = choice;
    if (choice.generation !== generation || choice.phase !== phase) {
        current = {
            generation,
            phase,
            expanded: choice.generation !== generation || streaming ? null : choice.expanded,
        };
        setChoice(current);
    }
    if (content.length === 0)
        return null;
    const expanded = current.expanded ?? (streaming || defaultExpanded);
    const text = label ||
        (streaming
            ? 'Thinking…'
            : durationMs === undefined
                ? 'Show reasoning'
                : `Thought for ${formatDuration(durationMs)}`);
    return (<div className={['tp-reasoning', className].filter(Boolean).join(' ')}>
      <button id={`${id}-toggle`} type="button" className="tp-reasoning__toggle" aria-expanded={expanded} aria-controls={`${id}-body`} onClick={() => setChoice({ ...current, expanded: !expanded })}>
        <span aria-hidden="true">{expanded ? '▾' : '▸'}</span> {text}
      </button>
      <div id={`${id}-body`} role="region" aria-label="Reasoning" hidden={!expanded} className="tp-reasoning__body">
        <Markdown snapshot={snapshot}/>
      </div>
    </div>);
}

