export function ThreadList({ threads, onSelect, activeThreadId, label = 'Conversations', className, onNewThread, newThreadDisabled = false, newThreadLabel = '+ New thread', now = Date.now(), renderItem, renderTitle, renderActions, onContextMenu, }: ThreadListProps) {
    const listId = useId();
    const keyboardContext = useRef<HTMLButtonElement | null>(null);
    const reference = validDate(now);
    const list = (<ul className={`tp-thread-list${className ? ` ${className}` : ''}`} aria-label={label}>
      {threads.map((thread, index) => {
            if (renderItem) {
                return (<li key={thread.id} className="tp-thread-list__item">
              {renderItem(thread, thread.id === activeThreadId)}
            </li>);
            }
            const pinned = thread.pinned === true;
            const title = thread.title || thread.id;
            const content = renderTitle ? renderTitle(thread) : title;
            const actions = renderActions?.(thread);
            const hasActions = actions !== null && actions !== false && actions !== undefined;
            const updated = validDate(thread.updatedAt);
            const time = reference && updated && thread.updatedAt !== undefined
                ? relativeTime(now - thread.updatedAt)
                : undefined;
            const rowId = `${listId}-${index}`;
            return (<li key={thread.id} className={`tp-thread-list__item${hasActions ? ' tp-thread-list__item--actions' : ''}`}>
            <button type="button" className="tp-thread-list__button" title={title} aria-label={renderTitle || pinned ? title : undefined} aria-labelledby={time && !renderTitle && !pinned ? `${rowId}-title` : undefined} aria-describedby={pinned
                    ? `${rowId}-pinned${time ? ` ${rowId}-time` : ''}`
                    : time
                        ? `${rowId}-time`
                        : undefined} aria-current={thread.id === activeThreadId ? 'true' : undefined} onClick={() => onSelect(thread.id)} onPointerDown={onContextMenu
                    ? () => {
                        keyboardContext.current = null;
                    }
                    : undefined} onContextMenu={onContextMenu
                    ? (event) => {
                        if (event.defaultPrevented)
                            return;
                        const duplicate = keyboardContext.current === event.currentTarget &&
                            event.button === 0;
                        keyboardContext.current = null;
                        if (duplicate) {
                            event.preventDefault();
                            return;
                        }
                        onContextMenu(thread.id, event);
                    }
                    : undefined} onKeyDown={onContextMenu
                    ? (event) => {
                        if (event.defaultPrevented ||
                            event.repeat ||
                            event.nativeEvent.isComposing ||
                            event.ctrlKey ||
                            event.metaKey ||
                            event.altKey)
                            return;
                        if (!((event.key === 'ContextMenu' && !event.shiftKey) ||
                            (event.key === 'F10' && event.shiftKey)))
                            return;
                        const button = event.currentTarget;
                        onContextMenu(thread.id, event);
                        keyboardContext.current = event.defaultPrevented
                            ? button
                            : null;
                    }
                    : undefined}>
              {pinned && (<svg className="tp-thread-list__pin" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">
                  <path d="M16 12V4h1V2H7v2h1v8l-2 2v2h5.2v6h1.6v-6H18v-2l-2-2z"/>
                </svg>)}
              {time && updated ? (<>
                  <span id={`${rowId}-title`}>{content}</span>
                  <time id={`${rowId}-time`} className="tp-thread-list__time" dateTime={updated.toISOString()}>
                    {time}
                  </time>
                </>) : (content)}
              {pinned && (<span id={`${rowId}-pinned`} className="tp-thread-list__status">
                  Pinned conversation
                </span>)}
            </button>
            {hasActions && (<div className="tp-thread-list__actions">{actions}</div>)}
          </li>);
        })}
    </ul>);
    return onNewThread ? (<div className="tp-thread-list__container">
      <button type="button" className="tp-thread-list__new" onClick={() => onNewThread()} disabled={newThreadDisabled}>
        {newThreadLabel}
      </button>
      {list}
    </div>) : (list);
}

