export function ToolActivity({ activity: input, children, onRetry, grouped = false, retrying, }: ToolActivityProps) {
    const activity = resolveToolOutcome(input, input.outcome);
    const phase = activity.phase ?? 'unknown';
    const retry = onRetry && !grouped ? activityFailures([activity])[0]?.retry : undefined;
    return (<section className="tp-tool-activity" data-phase={phase} data-tool-id={activity.id}>
      <div className="tp-tool-activity__heading">
        <span className={grouped ? 'tp-tool-activity__label' : undefined} data-active={grouped ? phase === 'running' : undefined}>
          {activity.label ?? 'Tool activity'}
        </span>
        <span className="tp-tool-activity__phase">{labels[phase]}</span>
        {activity.durationMs !== undefined &&
            Number.isFinite(activity.durationMs) &&
            activity.durationMs >= 0 && (<span className="tp-tool-activity__duration">
              {activity.durationMs}ms
            </span>)}
      </div>
      {phase === 'error' && !grouped && retrying && (<p className="tp-tool-activity__label tp-tool-activity__retrying" data-active="true">
          {retrying}
        </p>)}
      {phase === 'error' && !grouped && (<p className="tp-tool-activity__error" role="alert">
          {activity.errorSummary ??
                'This tool could not finish. Check Details before retrying.'}
        </p>)}
      {retry && onRetry && (<button type="button" className="tp-tool-activity__retry" onClick={() => onRetry(retry.activity)}>
          {retry.label}
        </button>)}
      <details className="tp-tool-activity__details">
        <summary>Details</summary>
        <dl>
          <dt>Tool</dt>
          <dd>
            <code>{activity.name}</code>
          </dd>
          <dt>Call ID</dt>
          <dd>
            <code>{activity.id}</code>
          </dd>
        </dl>
        {activity.argumentsText !== undefined && (<>
            <p>Arguments</p>
            <pre>{activity.argumentsText}</pre>
          </>)}
        {activity.resultText !== undefined && (<>
            <p>Result</p>
            <pre>{activity.resultText}</pre>
          </>)}
        {activity.errorText !== undefined && (<>
            <p>Error</p>
            <pre>{activity.errorText}</pre>
          </>)}
      </details>
      <ToolOutcomes activities={[activity]}/>
      <ToolReceipts activities={[activity]}/>
      {children}
    </section>);
}

export type ToolActivityDelivery = {
    readonly phase: 'streaming';
} | {
    readonly phase: 'complete';
    readonly outcome: 'success' | 'error' | 'aborted' | 'interrupted' | 'paused';
};

export function ToolActivityGroup({ activities: input, label, renderResult, onRetry, context, retrying, plan, onStop, children, }: ToolActivityGroupProps) {
    const activities = input.map((activity) => resolveToolOutcome(activity, activity.outcome));
    const summary = activitySummary(activities, label);
    const [open, setOpen] = useState(false);
    const elapsed = useElapsed(summary.active);
    const upcoming = summary.active
        ? plan?.filter((step) => step.status === 'pending') ?? []
        : [];
    const failed = summary.phase === 'error';
    const failures = activityFailures(activities, context);
    const receipts = receiptOutcomes(activities);
    const results = renderResult
        ? activities.flatMap((activity) => {
            const result = renderResult(activity);
            return result === null || result === undefined
                ? []
                : [
                    <div key={activity.id} data-tool-id={activity.id}>
                {result}
              </div>,
                ];
        })
        : [];
    return (<section className="tp-tool-activity-group" data-phase={summary.phase} data-active={summary.active}>
      {activities.length > 0 && (<details className="tp-tool-activity-group__details" onToggle={(event) => setOpen(event.currentTarget.open)}>
          <summary>

            <span className="tp-tool-activity__label" data-active={summary.active && !open}>
              {summary.active && open && label === undefined
                ? workingLabel(activities)
                : summary.label}
            </span>
            {summary.cue && (<span className="tp-tool-activity__cue">{summary.cue}</span>)}
          </summary>
          <div className="tp-tool-activity-group__items">
            {activities.map((activity) => (<ToolActivity key={activity.id} activity={{ ...activity, outcome: undefined }} grouped>
                {open && <ToolOutcomes activities={[activity]} show="sources"/>}
              </ToolActivity>))}
            {upcoming.map((step, index) => (<p key={index} className="tp-tool-activity-group__plan-step">
                {step.label}
              </p>))}
          </div>
        </details>)}
      {summary.active && (elapsed !== undefined || onStop) && (<div className="tp-tool-activity-group__progress">
          {elapsed !== undefined && (<span className="tp-tool-activity-group__elapsed">{elapsed}</span>)}
          {onStop && (<button type="button" className="tp-tool-activity-group__stop" onClick={onStop}>
              Stop
            </button>)}
        </div>)}
      {activities.length > 0 && (<p role="status" aria-live="polite" aria-atomic="true" className="tp-tool-activity__status">
          {summary.status}
          {receipts.map((receipt) => ` ${receipt.lead} ${receipt.text}`)}
        </p>)}
      <ToolOutcomes activities={activities} show={open ? 'outcomes' : 'all'}/>
      {failed && (<StatusPanel tone="danger" role="alert" className="tp-tool-activity__error">
          {retrying && (<p className="tp-tool-activity__label tp-tool-activity__retrying" data-active="true">
              {retrying}
            </p>)}
          {failures.length > 0 ? (failures.flatMap(({ key, text, retry }) => [
                <p key={key}>{text}</p>,
                retry && onRetry && (<button key={`${key}-retry`} type="button" className="tp-tool-activity__retry" onClick={() => onRetry(retry.activity)}>
                  {retry.label}
                </button>),
            ])) : (<p>Some tools could not finish. Check Details before retrying.</p>)}
        </StatusPanel>)}
      <ToolReceipts activities={activities}/>
      {results.length > 0 && (<div className="tp-tool-activity__results">{results}</div>)}
      {children}
    </section>);
}

