export function isTyping(snapshot: Pick<AgentSnapshot, 'status' | 'messages'>): boolean {
    if (snapshot.status !== 'running')
        return false;
    const last = snapshot.messages.at(-1);
    return (!last ||
        last.role === 'user' ||
        (last.role === 'assistant' && last.content.length === 0));
}

export function resolveToolOutcome(activity: ToolActivityInfo, outcome: ToolActivityOutcome | undefined): ToolActivityInfo {
    if (activity.phase === 'complete' && outcome?.status === 'failed') {
        return {
            ...activity,
            phase: 'error',
            errorSummary: outcome.text.trim() || undefined,
            outcome,
        };
    }
    return { ...activity, outcome };
}

export function toolActivityPhase(phase: ToolActivityPhase | undefined, delivery?: ToolActivityDelivery): ToolActivityPhase {
    if (phase !== 'pending' && phase !== 'running')
        return phase ?? 'unknown';
    if (delivery?.phase !== 'complete')
        return phase;
    return delivery.outcome === 'aborted'
        ? 'stopped'
        : delivery.outcome === 'paused'
            ? 'waiting'
            : delivery.outcome === 'success' && phase === 'pending'
                ? 'pending'
                : 'unknown';
}

export function toolOutcomes(decoders: Readonly<Record<string, ToolOutcomeDecoder>>): (activity: ToolActivityInfo) => ToolActivityOutcome | undefined {
    const parse = (text: string | undefined, fallback: unknown): unknown => {
        if (text === undefined)
            return fallback;
        try {
            return JSON.parse(text);
        }
        catch {
            return fallback;
        }
    };
    return (activity) => {
        if (activity.phase !== 'complete' ||
            activity.resultText === undefined ||
            !Object.hasOwn(decoders, activity.name))
            return undefined;
        return decoders[activity.name]({
            activity,
            args: parse(activity.argumentsText, undefined),
            result: parse(activity.resultText, activity.resultText),
        });
    };
}

