@Injectable({ providedIn: 'root' })
export class ThreadplaneTelemetryService {
    private config: ThreadplaneTelemetryConfig | null = inject(THREADPLANE_TELEMETRY_CONFIG, { optional: true });
    private postHogPromise: Promise<typeof import('posthog-js')['default'] | null> | null = null;
    private distinctId: string | null = null;
    async capture(event: ThreadplaneTelemetryEvent, properties?: Record<string, unknown>): Promise<void> {
        if (!this.config?.enabled)
            return;
        const sampleRate = normalizeSampleRate(this.config.sampleRate);
        if (sampleRate === 0)
            return;
        if (sampleRate < 1 && Math.random() >= sampleRate)
            return;
        const enrichedProperties = {
            ...(properties ?? {}),
            sample_weight: properties?.['sample_weight'] ?? 1 / sampleRate,
        };
        try {
            if (this.config.sink) {
                await this.config.sink({ event, properties: enrichedProperties });
                return;
            }
            if (this.config.endpoint) {
                await this.captureEndpoint(event, enrichedProperties);
                return;
            }
            if (!this.config.posthogKey)
                return;
            const ph = await this.loadPostHog();
            if (!ph)
                return;
            ph.capture(event, enrichedProperties);
        }
        catch {
        }
    }
    captureRuntimeInstanceCreated(input: ThreadplaneBrowserRuntimeTelemetry): Promise<void> {
        return this.capture('tplane:runtime_instance_created', { ...input });
    }
    captureRuntimeRequestCreated(input: ThreadplaneBrowserRuntimeTelemetry & {
        requestType: string;
    }): Promise<void> {
        return this.capture('tplane:runtime_request_created', { ...input });
    }
    captureStreamStarted(input: ThreadplaneBrowserStreamTelemetry): Promise<void> {
        return this.capture('tplane:stream_started', { ...input });
    }
    captureStreamEnded(input: ThreadplaneBrowserStreamTelemetry): Promise<void> {
        return this.capture('tplane:stream_ended', { ...input });
    }
    captureStreamErrored(input: ThreadplaneBrowserStreamErrorTelemetry): Promise<void> {
        const { error, ...rest } = input;
        return this.capture('tplane:stream_errored', {
            ...rest,
            errorClass: errorClass(error),
        });
    }
    private async captureEndpoint(event: ThreadplaneTelemetryEvent, properties: Record<string, unknown>): Promise<void> {
        if (typeof fetch !== 'function' || !this.config?.endpoint)
            return;
        await fetch(this.config.endpoint, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            keepalive: true,
            body: JSON.stringify({
                event,
                distinctId: this.getDistinctId(),
                properties,
            }),
        });
    }
    private getDistinctId(): string {
        if (!this.distinctId) {
            const cryptoApi = globalThis.crypto as Crypto | undefined;
            const value = typeof cryptoApi?.randomUUID === 'function'
                ? cryptoApi.randomUUID()
                : Math.random().toString(36).slice(2, 12);
            this.distinctId = `browser:${value}`;
        }
        return this.distinctId;
    }
    private loadPostHog(): Promise<typeof import('posthog-js')['default'] | null> {
        if (!this.postHogPromise) {
            this.postHogPromise = import('posthog-js').then((mod) => {
                if (!this.config?.posthogKey)
                    return null;
                mod.default.init(this.config.posthogKey, {
                    api_host: this.config.posthogHost ?? 'https://us.i.posthog.com',
                });
                return mod.default;
            }).catch(() => null);
        }
        return this.postHogPromise;
    }
}

export function createDevelopmentRuntime(options: DevelopmentRuntimeOptions): DevelopmentRuntime {
    let disposed = false;
    const owner: RuntimeOwner = {
        options: {
            ...options,
            installationToken: typeof options.installationToken === 'string' &&
                UUID.test(options.installationToken)
                ? options.installationToken
                : undefined,
        },
        allowed: () => {
            try {
                return (!disposed &&
                    (options.enabled?.() ?? true) &&
                    ['langgraph', 'ag-ui', 'render'].includes(options.integration) &&
                    options.packageName === `@threadplane/${options.integration}` &&
                    /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/u.test(options.packageVersion) &&
                    options.packageVersion.length <= 64 &&
                    browserAllowed());
            }
            catch {
                return false;
            }
        },
    };
    const use = (kind?: Parameters<DevelopmentRuntime['milestone']>[0], durationMs?: number) => {
        try {
            if (!owner.allowed()) {
                collector?.prune();
                return;
            }
            collector ??= new DevelopmentCollector();
            collector.touch(owner, kind, durationMs);
        }
        catch {
        }
    };
    return {
        touch: () => use(),
        milestone: (kind, durationMs) => {
            if (MILESTONES.includes(kind))
                use(kind, durationMs);
        },
        dispose: () => {
            disposed = true;
            collector?.prune();
        },
    };
}

export function getDevelopmentCollectionDiagnostics() {
    return (collector?.diagnostics() ?? {
        discarded: 0,
        failures: 0,
        acknowledged: 0,
        pending: 0,
    });
}

export function isDevelopmentRuntimeEnabled(agent: object): boolean {
    try {
        return policies.get(agent)?.() === true;
    }
    catch {
        return false;
    }
}

export function isLocalAnalyticsHost(host: unknown): boolean {
    const value = toSafeString(host, 300)?.toLowerCase();
    if (!value)
        return false;
    if (value === '::1' || value.startsWith('[::1]'))
        return true;
    const hostname = value.split(':')[0];
    return hostname === 'localhost' || hostname === '127.0.0.1';
}

export function provideThreadplaneTelemetry(config: ThreadplaneTelemetryConfig): EnvironmentProviders {
    return makeEnvironmentProviders([
        { provide: THREADPLANE_TELEMETRY_CONFIG, useValue: config },
        ThreadplaneTelemetryService,
    ]);
}

export function registerDevelopmentRuntimePolicy<T extends object>(agent: T, policy: () => boolean): T {
    policies.set(agent, policy);
    return agent;
}

export function setDevelopmentCollectionEnabled(value: boolean): void {
    enabled = value === true;
    if (!enabled)
        collector?.clear();
}

export function shouldCaptureAnalytics({ token, captureLocal = false, host }: CaptureConfig): boolean {
    if (!toSafeString(token, 500))
        return false;
    if (isLocalAnalyticsHost(host) && !captureLocal)
        return false;
    return true;
}

export function getAnonId(): string {
    if (!cached)
        cached = `anon_${randomUUID()}`;
    return cached;
}

export function getDisableReason(env: NodeJS.ProcessEnv = process.env): DisableReason {
    if (truthy(env.DO_NOT_TRACK) || truthy(env.npm_config_do_not_track) || truthy(env.NPM_CONFIG_DO_NOT_TRACK)) {
        return 'DO_NOT_TRACK';
    }
    if (truthy(env.TPLANE_TELEMETRY_DISABLED))
        return 'TPLANE_TELEMETRY_DISABLED';
    if (truthy(env.CI) ||
        truthy(env.GITHUB_ACTIONS) ||
        truthy(env.CONTINUOUS_INTEGRATION) ||
        truthy(env.BUILDKITE) ||
        truthy(env.CIRCLECI)) {
        return 'CI';
    }
    return null;
}

export function isTelemetryDisabled(env: NodeJS.ProcessEnv = process.env): boolean {
    return getDisableReason(env) !== null;
}

export async function sha256(input: string): Promise<string> {
    const data = new TextEncoder().encode(input);
    const buf = await crypto.subtle.digest('SHA-256', data);
    return Array.from(new Uint8Array(buf))
        .map((b) => b.toString(16).padStart(2, '0'))
        .join('');
}

export function shouldSample(rate: number, anonId: string): boolean {
    if (rate <= 0)
        return false;
    if (rate >= 1)
        return true;
    return hashString(anonId) / 0xffffffff < rate;
}

export type CaptureResult = {
    sent: true;
} | {
    sent: false;
    reason: 'disabled' | 'sampled' | 'failed' | 'invalid';
};

export interface RuntimeInstanceTelemetry {
    transport: string;
    provider?: string;
    model?: string;
    angularVersion?: string;
    apiKey?: string;
}

export interface RuntimeRequestTelemetry {
    transport: string;
    requestType: string;
    provider?: string;
    model?: string;
}

export interface StreamTelemetry {
    transport?: string;
    provider: string;
    model: string;
    durationMs?: number;
}

export async function captureEvent(event: ThreadplaneNodeEvent, properties: Record<string, unknown> = {}): Promise<CaptureResult> {
    if (isTelemetryDisabled() || isProgrammaticallyDisabled())
        return { sent: false, reason: 'disabled' };
    const parsed = parseTelemetryEvent(event, properties);
    if (!parsed || parsed.event.startsWith('tplane:browser_'))
        return { sent: false, reason: 'invalid' };
    const rate = getSampleRate();
    const anonId = getAnonId();
    if (!shouldSample(rate, anonId))
        return { sent: false, reason: 'sampled' };
    const payload = parseTelemetryEvent(parsed.event, {
        ...parsed.properties,
        sample_weight: rate > 0 ? 1 / Math.min(1, rate) : 1,
    });
    if (!payload)
        return { sent: false, reason: 'invalid' };
    try {
        await postJson(process.env.TPLANE_TELEMETRY_INGEST_URL ?? DEFAULT_INGEST, {
            key: PUBLIC_INGEST_KEY,
            distinctId: anonId,
            event: payload.event,
            properties: payload.properties,
        });
        return { sent: true };
    }
    catch {
        return { sent: false, reason: 'failed' };
    }
}

export async function captureRuntimeInstanceCreated(input: RuntimeInstanceTelemetry): Promise<void> {
    await safe(async () => {
        const { apiKey, ...rest } = input;
        void apiKey;
        await captureEvent('tplane:runtime_instance_created', { ...rest });
    });
}

export async function captureRuntimeRequestCreated(input: RuntimeRequestTelemetry): Promise<void> {
    await safe(() => captureEvent('tplane:runtime_request_created', { ...input }));
}

export async function captureStreamEnded(input: StreamTelemetry): Promise<void> {
    await safe(async () => {
        const properties = streamProperties(input);
        if (properties)
            await captureEvent('tplane:stream_ended', properties);
    });
}

export async function captureStreamErrored(input: StreamTelemetry & {
    error: Error | unknown;
}): Promise<void> {
    await safe(async () => {
        const properties = streamProperties(input);
        if (!properties)
            return;
        const { error, ...rest } = input;
        const errorClass = error instanceof Error ? error.constructor.name : 'Unknown';
        await captureEvent('tplane:stream_errored', { ...rest, transport: properties['transport'], errorClass });
    });
}

export async function captureStreamStarted(input: StreamTelemetry): Promise<void> {
    await safe(async () => {
        const properties = streamProperties(input);
        if (properties)
            await captureEvent('tplane:stream_started', properties);
    });
}

export function disableTelemetry(): void {
    disabled = true;
}

export interface ParsedTelemetryEvent {
    event: ThreadplaneEvent;
    properties: Record<string, string | number>;
}

export function getEmailDomain(email: unknown): string | null {
    const value = toSafeAnalyticsString(email, 320);
    if (!value)
        return null;
    const atIndex = value.lastIndexOf('@');
    if (atIndex <= 0 || atIndex === value.length - 1)
        return null;
    const domain = value.slice(atIndex + 1).toLowerCase();
    return domain.includes('.') ? domain : null;
}

export function getSourcePage(value: unknown): string {
    const source = toSafeAnalyticsString(value, 2000);
    if (!source)
        return '/';
    if (source.startsWith('/'))
        return source;
    try {
        const url = new URL(source);
        return `${url.pathname}${url.search}${url.hash}` || '/';
    }
    catch {
        return '/';
    }
}

export function isPersonalEmailDomain(domain: string | null | undefined): boolean {
    if (!domain)
        return false;
    return PERSONAL_EMAIL_DOMAINS.has(domain.toLowerCase());
}

export function normalizePostHogHost(host: unknown): string {
    const value = toSafeAnalyticsString(host, 500);
    if (!value)
        return DEFAULT_POSTHOG_HOST;
    return value.endsWith('/') ? value.slice(0, -1) : value;
}

export function parseTelemetryEvent(event: unknown, properties: unknown): ParsedTelemetryEvent | null {
    try {
        if (typeof event !== 'string' || !EVENTS.has(event))
            return null;
        if (properties === null || typeof properties !== 'object' || Array.isArray(properties))
            return null;
        const prototype = Object.getPrototypeOf(properties);
        if (prototype !== Object.prototype && prototype !== null)
            return null;
        const result: Record<string, string | number> = {};
        for (const [key, descriptor] of Object.entries(Object.getOwnPropertyDescriptors(properties))) {
            if (!STRING_PROPERTIES.has(key) && key !== 'durationMs' && key !== 'sample_weight')
                continue;
            if (!('value' in descriptor))
                return null;
            const value: unknown = descriptor.value;
            if (value === undefined)
                continue;
            if (STRING_PROPERTIES.has(key)) {
                if (typeof value !== 'string' || /[\u0000-\u001f\u007f]/u.test(value))
                    return null;
                const label = value.trim();
                if (!label || label.length > 128)
                    return null;
                result[key] = label;
            }
            else {
                if (typeof value !== 'number' || !Number.isFinite(value))
                    return null;
                if (key === 'durationMs' && (value < 0 || value > 86400000))
                    return null;
                if (key === 'sample_weight' && value < 1)
                    return null;
                result[key] = value;
            }
        }
        if (event === 'tplane:browser_chat_init' && !result['surface'])
            return null;
        if (event !== 'tplane:browser_provided' && event !== 'tplane:browser_chat_init' && !result['transport'])
            return null;
        return { event: event as ThreadplaneEvent, properties: result };
    }
    catch {
        return null;
    }
}

export function toSafeAnalyticsString(value: unknown, maxLength = 200): string | undefined {
    if (typeof value !== 'string')
        return undefined;
    const trimmed = value.trim();
    if (!trimmed)
        return undefined;
    return trimmed.slice(0, maxLength);
}
